insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (100, 7, 1, 25, 'سورة الأعراف ١ – ٢٥', '«كتاب أُنزل إليك»، الوزن يومئذ الحق، وقصة آدم ﵇ وإبليس', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 100) = $j$[{"lbl": "الآيات ١ – ٥", "q": "الٓمٓصٓ ﴿١﴾ كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿٢﴾ ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٣﴾ وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ ﴿٤﴾ فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٥﴾", "w": [["المص", "هذه أحد الحروف المقطعة، ويُقرأ هكذا: ألف لام ميم صاد، والله أعلم بمراده بها."], ["كتاب", "أي هذا كتاب."], ["حرج", "ضيق."], ["وذكرى", "تذكرة بها يذكرون الله وما عنده وما لديه فيُقبلون على طاعته."], ["أولياء", "رؤساؤهم في الشرك."], ["ما تذكّرون", "تتّعظون فترجعون إلى الحق."], ["وكم من قرية", "أي كثيراً من القرى."], ["بأسنا بياتاً", "عذابنا ليلاً وهم نائمون."], ["أو هم قائلون", "نائمون بالقيلولة وهم مستريحون."], ["فما كان دعواهم", "أي دعاؤهم: قولهم إنا كنا ظالمين."]], "m": "«المص»: إشارة إلى أن هذا القرآن تألّف من مثل هذه الحروف المقطعة، وقد عجزتم عن تأليف مثله، فظهر أنه كلام الله فآمنوا به. هذا كتاب أُنزل إليك يا رسولنا، فلا يكن في صدرك ضيق منه، لتنذر به قومك عواقب شركهم وضلالهم، وذكرى للمؤمنين، وقل لهم: اتبعوا ما أُنزل إليكم من ربكم من الهدى والنور، ولا تتبعوا من دونه أولياء لا يأمرونكم إلا بالشرك والشر، وهم رؤساء الضلال في قريش، قليلاً ما تذكّرون فترجعون إلى الحق. وكثير من القرى أهلكنا أهلها لما جانبوا الحق ولازموا الباطل، فجاءها عذابنا الشديد ليلاً أو نهاراً وهم قائلون، فما كان دعاؤهم يومئذ إلا قولهم: إنا كنا ظالمين، فاعترفوا بذنبهم، ولكن هيهات أن ينفعهم الاعتراف بعد معاينة العذاب.", "h": ["القرآن الكريم هو مصدر نذارة الرسول ﷺ وبشارته، بما حواه من الوعد والوعيد، والذكرى والبشرى.", "وجوب اتباع الوحي، وحرمة اتباع ما يدعو إليه أصحاب الأهواء والمبتدعة.", "الاعتبار بما حلّ بالأمم الظالمة من خراب ودمار.", "لا تنفع التوبة عند معاينة الموت أو العذاب."], "k": "«فلا يكن في صدرك حرج منه»… هل أضيق بشيء من أحكام القرآن، أم أتلقّاه بصدر منشرح؟"}, {"lbl": "الآيات ٦ – ١٠", "q": "فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ ﴿٦﴾ فَلَنَقُصَّنَّ عَلَيۡهِم بِعِلۡمٖۖ وَمَا كُنَّا غَآئِبِينَ ﴿٧﴾ وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٨﴾ وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظۡلِمُونَ ﴿٩﴾ وَلَقَدۡ مَكَّنَّـٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿١٠﴾", "w": [["أُرسل إليهم", "هم الأمم والأقوام."], ["فلنقصّنّ عليهم بعلم", "فلنخبرنّهم بأعمالهم متتبّعين لها، فلا نترك منها شيئاً."], ["وما كنا غائبين", "أي عنهم أيام كانوا يعملون."], ["فمن ثقلت موازينه", "أي بالحسنات، فأولئك هم المفلحون بدخول الجنة."], ["خسروا أنفسهم", "بدخولهم النار والاصطلاء بها أبداً."], ["قليلاً ما تشكرون", "شكراً قليلاً، والشكر: ذكر النعمة للمنعم، وطاعته بفعل محابّه وترك مكارهه."]], "m": "يخبر الله، مؤكّداً بالقسم، أنه إذا جمع الخلائق لفصل القضاء يسأل كل أمة أُرسل إليهم رسله عن مدى إجابتهم دعوتهم إلى التوحيد والطاعة، ويسأل المرسلين: هل بلّغوا ما ائتمنهم عليه؟ ثم يقصّ عليهم بعلمه كل ما كان منهم من ظاهر الأعمال وباطنها، ولم يكن سؤالهم إلا لإقامة الحجة وإظهار عدالته وتوبيخ من يستحق، وما كان غائباً عنهم حين كانوا يعملون. ثم يُنصب الميزان، والوزن يومئذ الحق، فمن ثقلت موازينه بحسناته أفلح بالنجاة من النار ودخول الجنة، ومن خفّت موازينه لقلة حسناته وكثرة سيئاته خسر نفسه بإلقائه في جهنم، بما كانوا بآياتنا يظلمون، أي يكذّبون ويجحدون، فكانوا كأنهم ظلموا الآيات إذ لم يؤمنوا بها وهي بيّنات. ولقد مكّناكم في الأرض تتصرّفون فيها وتمشون في مناكبها، وجعلنا لكم فيها معايش وأرزاقاً، وكان المفروض أن تشكروا بالإيمان والتوحيد والطاعة، ولكن قليلاً ما تشكرون، شكراً يسيراً لا يكاد يُذكر.", "h": ["تقرير عقيدة البعث والسؤال والحساب ووزن الأعمال يوم القيامة.", "صعوبة الموقف، حيث تُسأل الأمم والرسل ﵈ كذلك.", "الفلاح والخسران مبنيان على الكسب في الدنيا، فمن كسب خيراً نجا، ومن كسب شراً هلك."], "k": "«فمن ثقلت موازينه فأولئك هم المفلحون»… ماذا وضعت اليوم في كفّة حسناتي؟"}, {"lbl": "الآيات ١١ – ١٨", "q": "وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّـٰجِدِينَ ﴿١١﴾ قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ﴿١٢﴾ قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ ﴿١٣﴾ قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٤﴾ قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿١٥﴾ قَالَ فَبِمَآ أَغۡوَيۡتَنِي لَأَقۡعُدَنَّ لَهُمۡ صِرَٰطَكَ ٱلۡمُسۡتَقِيمَ ﴿١٦﴾ ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ ﴿١٧﴾ قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومٗا مَّدۡحُورٗاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِينَ ﴿١٨﴾", "w": [["خلقناكم ثم صوّرناكم", "خلقنا أباكم آدم، أي قدّرناه من الطين، ثم صوّرناه على الصورة البشرية الكريمة التي ورثها بنوه من بعده إلى نهاية الوجود."], ["فسجدوا", "سجود تحية لآدم ﵇."], ["إبليس", "أبو الشياطين من الجن، وكنيته أبو مرة، وهو الشيطان الرجيم."]], "m": "ما زال السياق في تعداد نعم الله الموجبة لشكره: ولقد خلقنا أباكم آدم من طين ثم صوّرناه بالصورة البشرية التي ورثها بنوه، ثم قلنا للملائكة اسجدوا لآدم تحية له وتعظيماً، وفي هذا تكريم لأبيكم، فسجدوا إلا إبليس أبى أن يسجد. قال: ما منعك ألّا تسجد إذ أمرتك؟ قال: أنا خير منه، خلقتني من نار وخلقته من طين، فأنا أشرف منه. ولم يكن مصيباً في هذا القياس الفاسد: فليست النار أشرف من الطين، بل الطين أكثر نفعاً وأقل ضرراً، ثم إن الذي أمره هو الرب الذي تجب طاعته، فاضلاً كان المسجود له أو مفضولاً. قال: فاهبط منها فما يكون لك أن تتكبّر فيها، فاخرج إنك من الصاغرين الذليلين. فلما عرف سبب هلكته قال: أنظرني إلى يوم يبعثون، قال: إنك من المنظرين، إلى يوم الوقت المعلوم، وهو فناء الدنيا قبل البعث. وكان مراده التمكّن من إفساد أكبر عدد من بني آدم انتقاماً، إذ كان آدم سبب طرده، فقال: فبما أغويتني لأقعدنّ لهم صراطك المستقيم، وهو الإسلام، ثم لآتينّهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم ليهلكوا كما هلك، ولا تجد أكثرهم شاكرين. قال: اخرج منها مذموماً ممقوتاً مدحوراً مطروداً، لمن تبعك منهم لأملأنّ جهنم منكم أجمعين.", "h": ["خطر الكبر على الإنسان.", "ضرر القياس الفاسد.", "خطر إبليس وذريته على بني آدم، والنجاة منهم بذكر الله تعالى وشكره."], "k": "«أنا خير منه»… متى قلتها في نفسي عن أحد، فمنعني الكبر من حق أو اعتذار؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "وَيَـٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ ﴿١٩﴾ فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ ﴿٢٠﴾ وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ ﴿٢١﴾ فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ ﴿٢٢﴾", "w": [["وزوجك", "هي حواء التي خلقها الله تعالى من ضلع آدم الأيسر."], ["الجنة", "دار السلام التي دخلها رسول الله ﷺ ليلة الإسراء والمعراج."], ["من الظالمين", "أي لأنفسهم."], ["فوسوس", "الوسوسة: الصوت الخفي، ووسوسة الشيطان لابن آدم: إلقاء معانٍ فاسدة ضارة في صدره مزيّنة ليعتقدها أو يقول بها أو يعمل."], ["ليُبدي ما وُوري", "ليُظهر لهما ما سُتر عنهما من عوراتهما."], ["وقاسمهما", "حلف لكل واحد منهما."], ["فدلّاهما بغرور", "أدناهما شيئاً فشيئاً بخداعه وتغريره حتى أكلا من الشجرة."], ["وطفقا يخصفان", "جعلا يشدّان عليهما من ورق الجنة ليسترا عوراتهما."]], "m": "لما طرد الرحمن إبليس نادى آدم: يا آدم اسكن أنت وزوجك حواء الجنة فكلا من حيث شئتما من ثمارها، ولا تقربا هذه الشجرة، شجرة معيّنة نهاهما عن الأكل منها، فتكونا من الظالمين المستوجبين للعقاب. واستغلّ إبليس الفرصة فوسوس لهما مزيّناً الأكل منها: ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين أو تكونا من الخالدين، وحلف لهما إني لكما لمن الناصحين، فأدناهما بخداعه حتى أكلا، فلما ذاقا الشجرة بدت لهما سوآتهما إذ انحسر النور الذي كان يغطّيهما، وطفقا يشدّان عليهما من ورق الجنة ليسترا عوراتهما. وعندئذ ناداهما ربهما تأديباً وتأنيباً: ألم أنهكما عن تلكما الشجرة وأقل لكما إن الشيطان لكما عدو مبين؟ فكيف قبلتما نصحه وهو عدوكما؟", "h": ["سلاح إبليس الذي يحارب به ابن آدم هو الوسوسة والتزيين لا غير.", "تقرير عداوة الشيطان للإنسان.", "النهي يقتضي التحريم، إلا أن توجد قرينة تصرفه إلى الكراهة.", "وجوب ستر العورة من الرجال والنساء سواء.", "جواز الإقسام بالله تعالى، ولكن لا يحلف إلا صادقاً."], "k": "«إني لكما لمن الناصحين»… كم مرة جاءتني المعصية في ثوب النصيحة والمصلحة؟"}, {"lbl": "الآيات ٢٣ – ٢٥", "q": "قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿٢٣﴾ قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ ﴿٢٤﴾ قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ ﴿٢٥﴾", "w": [["ظلمنا أنفسنا", "أي بأكلهما من الشجرة."], ["مستقر", "مكان استقرار وإقامة."], ["متاع إلى حين", "تمتّع بالحياة إلى حين انقضاء آجالكم."]], "m": "لما ذاق آدم وحواء الشجرة وبدت لهما سوآتهما وعاتبهما ربهما، قالا معلنين توبتهما: ربنا ظلمنا أنفسنا بذوق الشجرة، وإن لم تغفر لنا خطيئتنا وترحمنا لنكوننّ من الخاسرين الهالكين، فتاب الله عليهما. وقال: اهبطوا إلى الأرض، إذ لم تعد الجنة داراً لهم بعد المعصية: إبليس بامتناعه عن السجود، وآدم وحواء بأكلهما من الشجرة، بعضكم لبعض عدو: إبليس وذريته عدو لآدم وبنيه، وآدم وبنوه عدو لإبليس وذريته، ولكم في الأرض مستقر ومتاع إلى حين انقضاء الآجال. فيها تحيون وفيها تموتون ومنها تُخرجون من القبور إلى البعث.", "h": ["قول آدم وحواء: «ربنا ظلمنا أنفسنا…» الآية، هو الكلمات التي ألقاها الله إلى آدم فتلقّاها عنه فتاب عليه بها.", "التوبة: الاعتراف بالذنب، وذلك بالاستغفار أي طلب المغفرة.", "شؤم الخطيئة كان سبب طرد إبليس من الرحمة، وإخراج آدم من الجنة.", "لا تتم حياة للإنسان على غير الأرض، ولا يُدفن بعد موته في غيرها، لدلالة آية «فيها تحيون وفيها تموتون ومنها تُخرجون»."], "k": "«ربنا ظلمنا أنفسنا»… كلمات أبي آدم بعد الزلّة؛ فهل أسرع إليها كما أسرع هو، أم أُكابر كما كابر إبليس؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 100;
insert into public.tdb_cards(topic, i, body) select 100, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ١ – ٥", "q": "الٓمٓصٓ ﴿١﴾ كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ﴿٢﴾ ٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ ﴿٣﴾ وَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ ﴿٤﴾ فَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ ﴿٥﴾", "w": [["المص", "هذه أحد الحروف المقطعة، ويُقرأ هكذا: ألف لام ميم صاد، والله أعلم بمراده بها."], ["كتاب", "أي هذا كتاب."], ["حرج", "ضيق."], ["وذكرى", "تذكرة بها يذكرون الله وما عنده وما لديه فيُقبلون على طاعته."], ["أولياء", "رؤساؤهم في الشرك."], ["ما تذكّرون", "تتّعظون فترجعون إلى الحق."], ["وكم من قرية", "أي كثيراً من القرى."], ["بأسنا بياتاً", "عذابنا ليلاً وهم نائمون."], ["أو هم قائلون", "نائمون بالقيلولة وهم مستريحون."], ["فما كان دعواهم", "أي دعاؤهم: قولهم إنا كنا ظالمين."]], "m": "«المص»: إشارة إلى أن هذا القرآن تألّف من مثل هذه الحروف المقطعة، وقد عجزتم عن تأليف مثله، فظهر أنه كلام الله فآمنوا به. هذا كتاب أُنزل إليك يا رسولنا، فلا يكن في صدرك ضيق منه، لتنذر به قومك عواقب شركهم وضلالهم، وذكرى للمؤمنين، وقل لهم: اتبعوا ما أُنزل إليكم من ربكم من الهدى والنور، ولا تتبعوا من دونه أولياء لا يأمرونكم إلا بالشرك والشر، وهم رؤساء الضلال في قريش، قليلاً ما تذكّرون فترجعون إلى الحق. وكثير من القرى أهلكنا أهلها لما جانبوا الحق ولازموا الباطل، فجاءها عذابنا الشديد ليلاً أو نهاراً وهم قائلون، فما كان دعاؤهم يومئذ إلا قولهم: إنا كنا ظالمين، فاعترفوا بذنبهم، ولكن هيهات أن ينفعهم الاعتراف بعد معاينة العذاب.", "h": ["القرآن الكريم هو مصدر نذارة الرسول ﷺ وبشارته، بما حواه من الوعد والوعيد، والذكرى والبشرى.", "وجوب اتباع الوحي، وحرمة اتباع ما يدعو إليه أصحاب الأهواء والمبتدعة.", "الاعتبار بما حلّ بالأمم الظالمة من خراب ودمار.", "لا تنفع التوبة عند معاينة الموت أو العذاب."], "k": "«فلا يكن في صدرك حرج منه»… هل أضيق بشيء من أحكام القرآن، أم أتلقّاه بصدر منشرح؟"}, {"lbl": "الآيات ٦ – ١٠", "q": "فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ ﴿٦﴾ فَلَنَقُصَّنَّ عَلَيۡهِم بِعِلۡمٖۖ وَمَا كُنَّا غَآئِبِينَ ﴿٧﴾ وَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ﴿٨﴾ وَمَنۡ خَفَّتۡ مَوَٰزِينُهُۥ فَأُوْلَـٰٓئِكَ ٱلَّذِينَ خَسِرُوٓاْ أَنفُسَهُم بِمَا كَانُواْ بِـَٔايَٰتِنَا يَظۡلِمُونَ ﴿٩﴾ وَلَقَدۡ مَكَّنَّـٰكُمۡ فِي ٱلۡأَرۡضِ وَجَعَلۡنَا لَكُمۡ فِيهَا مَعَٰيِشَۗ قَلِيلٗا مَّا تَشۡكُرُونَ ﴿١٠﴾", "w": [["أُرسل إليهم", "هم الأمم والأقوام."], ["فلنقصّنّ عليهم بعلم", "فلنخبرنّهم بأعمالهم متتبّعين لها، فلا نترك منها شيئاً."], ["وما كنا غائبين", "أي عنهم أيام كانوا يعملون."], ["فمن ثقلت موازينه", "أي بالحسنات، فأولئك هم المفلحون بدخول الجنة."], ["خسروا أنفسهم", "بدخولهم النار والاصطلاء بها أبداً."], ["قليلاً ما تشكرون", "شكراً قليلاً، والشكر: ذكر النعمة للمنعم، وطاعته بفعل محابّه وترك مكارهه."]], "m": "يخبر الله، مؤكّداً بالقسم، أنه إذا جمع الخلائق لفصل القضاء يسأل كل أمة أُرسل إليهم رسله عن مدى إجابتهم دعوتهم إلى التوحيد والطاعة، ويسأل المرسلين: هل بلّغوا ما ائتمنهم عليه؟ ثم يقصّ عليهم بعلمه كل ما كان منهم من ظاهر الأعمال وباطنها، ولم يكن سؤالهم إلا لإقامة الحجة وإظهار عدالته وتوبيخ من يستحق، وما كان غائباً عنهم حين كانوا يعملون. ثم يُنصب الميزان، والوزن يومئذ الحق، فمن ثقلت موازينه بحسناته أفلح بالنجاة من النار ودخول الجنة، ومن خفّت موازينه لقلة حسناته وكثرة سيئاته خسر نفسه بإلقائه في جهنم، بما كانوا بآياتنا يظلمون، أي يكذّبون ويجحدون، فكانوا كأنهم ظلموا الآيات إذ لم يؤمنوا بها وهي بيّنات. ولقد مكّناكم في الأرض تتصرّفون فيها وتمشون في مناكبها، وجعلنا لكم فيها معايش وأرزاقاً، وكان المفروض أن تشكروا بالإيمان والتوحيد والطاعة، ولكن قليلاً ما تشكرون، شكراً يسيراً لا يكاد يُذكر.", "h": ["تقرير عقيدة البعث والسؤال والحساب ووزن الأعمال يوم القيامة.", "صعوبة الموقف، حيث تُسأل الأمم والرسل ﵈ كذلك.", "الفلاح والخسران مبنيان على الكسب في الدنيا، فمن كسب خيراً نجا، ومن كسب شراً هلك."], "k": "«فمن ثقلت موازينه فأولئك هم المفلحون»… ماذا وضعت اليوم في كفّة حسناتي؟"}, {"lbl": "الآيات ١١ – ١٨", "q": "وَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَـٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّـٰجِدِينَ ﴿١١﴾ قَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ﴿١٢﴾ قَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّـٰغِرِينَ ﴿١٣﴾ قَالَ أَنظِرۡنِيٓ إِلَىٰ يَوۡمِ يُبۡعَثُونَ ﴿١٤﴾ قَالَ إِنَّكَ مِنَ ٱلۡمُنظَرِينَ ﴿١٥﴾ قَالَ فَبِمَآ أَغۡوَيۡتَنِي لَأَقۡعُدَنَّ لَهُمۡ صِرَٰطَكَ ٱلۡمُسۡتَقِيمَ ﴿١٦﴾ ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ ﴿١٧﴾ قَالَ ٱخۡرُجۡ مِنۡهَا مَذۡءُومٗا مَّدۡحُورٗاۖ لَّمَن تَبِعَكَ مِنۡهُمۡ لَأَمۡلَأَنَّ جَهَنَّمَ مِنكُمۡ أَجۡمَعِينَ ﴿١٨﴾", "w": [["خلقناكم ثم صوّرناكم", "خلقنا أباكم آدم، أي قدّرناه من الطين، ثم صوّرناه على الصورة البشرية الكريمة التي ورثها بنوه من بعده إلى نهاية الوجود."], ["فسجدوا", "سجود تحية لآدم ﵇."], ["إبليس", "أبو الشياطين من الجن، وكنيته أبو مرة، وهو الشيطان الرجيم."]], "m": "ما زال السياق في تعداد نعم الله الموجبة لشكره: ولقد خلقنا أباكم آدم من طين ثم صوّرناه بالصورة البشرية التي ورثها بنوه، ثم قلنا للملائكة اسجدوا لآدم تحية له وتعظيماً، وفي هذا تكريم لأبيكم، فسجدوا إلا إبليس أبى أن يسجد. قال: ما منعك ألّا تسجد إذ أمرتك؟ قال: أنا خير منه، خلقتني من نار وخلقته من طين، فأنا أشرف منه. ولم يكن مصيباً في هذا القياس الفاسد: فليست النار أشرف من الطين، بل الطين أكثر نفعاً وأقل ضرراً، ثم إن الذي أمره هو الرب الذي تجب طاعته، فاضلاً كان المسجود له أو مفضولاً. قال: فاهبط منها فما يكون لك أن تتكبّر فيها، فاخرج إنك من الصاغرين الذليلين. فلما عرف سبب هلكته قال: أنظرني إلى يوم يبعثون، قال: إنك من المنظرين، إلى يوم الوقت المعلوم، وهو فناء الدنيا قبل البعث. وكان مراده التمكّن من إفساد أكبر عدد من بني آدم انتقاماً، إذ كان آدم سبب طرده، فقال: فبما أغويتني لأقعدنّ لهم صراطك المستقيم، وهو الإسلام، ثم لآتينّهم من بين أيديهم ومن خلفهم وعن أيمانهم وعن شمائلهم ليهلكوا كما هلك، ولا تجد أكثرهم شاكرين. قال: اخرج منها مذموماً ممقوتاً مدحوراً مطروداً، لمن تبعك منهم لأملأنّ جهنم منكم أجمعين.", "h": ["خطر الكبر على الإنسان.", "ضرر القياس الفاسد.", "خطر إبليس وذريته على بني آدم، والنجاة منهم بذكر الله تعالى وشكره."], "k": "«أنا خير منه»… متى قلتها في نفسي عن أحد، فمنعني الكبر من حق أو اعتذار؟"}, {"lbl": "الآيات ١٩ – ٢٢", "q": "وَيَـٰٓـَٔادَمُ ٱسۡكُنۡ أَنتَ وَزَوۡجُكَ ٱلۡجَنَّةَ فَكُلَا مِنۡ حَيۡثُ شِئۡتُمَا وَلَا تَقۡرَبَا هَٰذِهِ ٱلشَّجَرَةَ فَتَكُونَا مِنَ ٱلظَّـٰلِمِينَ ﴿١٩﴾ فَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا وَقَالَ مَا نَهَىٰكُمَا رَبُّكُمَا عَنۡ هَٰذِهِ ٱلشَّجَرَةِ إِلَّآ أَن تَكُونَا مَلَكَيۡنِ أَوۡ تَكُونَا مِنَ ٱلۡخَٰلِدِينَ ﴿٢٠﴾ وَقَاسَمَهُمَآ إِنِّي لَكُمَا لَمِنَ ٱلنَّـٰصِحِينَ ﴿٢١﴾ فَدَلَّىٰهُمَا بِغُرُورٖۚ فَلَمَّا ذَاقَا ٱلشَّجَرَةَ بَدَتۡ لَهُمَا سَوۡءَٰتُهُمَا وَطَفِقَا يَخۡصِفَانِ عَلَيۡهِمَا مِن وَرَقِ ٱلۡجَنَّةِۖ وَنَادَىٰهُمَا رَبُّهُمَآ أَلَمۡ أَنۡهَكُمَا عَن تِلۡكُمَا ٱلشَّجَرَةِ وَأَقُل لَّكُمَآ إِنَّ ٱلشَّيۡطَٰنَ لَكُمَا عَدُوّٞ مُّبِينٞ ﴿٢٢﴾", "w": [["وزوجك", "هي حواء التي خلقها الله تعالى من ضلع آدم الأيسر."], ["الجنة", "دار السلام التي دخلها رسول الله ﷺ ليلة الإسراء والمعراج."], ["من الظالمين", "أي لأنفسهم."], ["فوسوس", "الوسوسة: الصوت الخفي، ووسوسة الشيطان لابن آدم: إلقاء معانٍ فاسدة ضارة في صدره مزيّنة ليعتقدها أو يقول بها أو يعمل."], ["ليُبدي ما وُوري", "ليُظهر لهما ما سُتر عنهما من عوراتهما."], ["وقاسمهما", "حلف لكل واحد منهما."], ["فدلّاهما بغرور", "أدناهما شيئاً فشيئاً بخداعه وتغريره حتى أكلا من الشجرة."], ["وطفقا يخصفان", "جعلا يشدّان عليهما من ورق الجنة ليسترا عوراتهما."]], "m": "لما طرد الرحمن إبليس نادى آدم: يا آدم اسكن أنت وزوجك حواء الجنة فكلا من حيث شئتما من ثمارها، ولا تقربا هذه الشجرة، شجرة معيّنة نهاهما عن الأكل منها، فتكونا من الظالمين المستوجبين للعقاب. واستغلّ إبليس الفرصة فوسوس لهما مزيّناً الأكل منها: ما نهاكما ربكما عن هذه الشجرة إلا أن تكونا ملكين أو تكونا من الخالدين، وحلف لهما إني لكما لمن الناصحين، فأدناهما بخداعه حتى أكلا، فلما ذاقا الشجرة بدت لهما سوآتهما إذ انحسر النور الذي كان يغطّيهما، وطفقا يشدّان عليهما من ورق الجنة ليسترا عوراتهما. وعندئذ ناداهما ربهما تأديباً وتأنيباً: ألم أنهكما عن تلكما الشجرة وأقل لكما إن الشيطان لكما عدو مبين؟ فكيف قبلتما نصحه وهو عدوكما؟", "h": ["سلاح إبليس الذي يحارب به ابن آدم هو الوسوسة والتزيين لا غير.", "تقرير عداوة الشيطان للإنسان.", "النهي يقتضي التحريم، إلا أن توجد قرينة تصرفه إلى الكراهة.", "وجوب ستر العورة من الرجال والنساء سواء.", "جواز الإقسام بالله تعالى، ولكن لا يحلف إلا صادقاً."], "k": "«إني لكما لمن الناصحين»… كم مرة جاءتني المعصية في ثوب النصيحة والمصلحة؟"}, {"lbl": "الآيات ٢٣ – ٢٥", "q": "قَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ﴿٢٣﴾ قَالَ ٱهۡبِطُواْ بَعۡضُكُمۡ لِبَعۡضٍ عَدُوّٞۖ وَلَكُمۡ فِي ٱلۡأَرۡضِ مُسۡتَقَرّٞ وَمَتَٰعٌ إِلَىٰ حِينٖ ﴿٢٤﴾ قَالَ فِيهَا تَحۡيَوۡنَ وَفِيهَا تَمُوتُونَ وَمِنۡهَا تُخۡرَجُونَ ﴿٢٥﴾", "w": [["ظلمنا أنفسنا", "أي بأكلهما من الشجرة."], ["مستقر", "مكان استقرار وإقامة."], ["متاع إلى حين", "تمتّع بالحياة إلى حين انقضاء آجالكم."]], "m": "لما ذاق آدم وحواء الشجرة وبدت لهما سوآتهما وعاتبهما ربهما، قالا معلنين توبتهما: ربنا ظلمنا أنفسنا بذوق الشجرة، وإن لم تغفر لنا خطيئتنا وترحمنا لنكوننّ من الخاسرين الهالكين، فتاب الله عليهما. وقال: اهبطوا إلى الأرض، إذ لم تعد الجنة داراً لهم بعد المعصية: إبليس بامتناعه عن السجود، وآدم وحواء بأكلهما من الشجرة، بعضكم لبعض عدو: إبليس وذريته عدو لآدم وبنيه، وآدم وبنوه عدو لإبليس وذريته، ولكم في الأرض مستقر ومتاع إلى حين انقضاء الآجال. فيها تحيون وفيها تموتون ومنها تُخرجون من القبور إلى البعث.", "h": ["قول آدم وحواء: «ربنا ظلمنا أنفسنا…» الآية، هو الكلمات التي ألقاها الله إلى آدم فتلقّاها عنه فتاب عليه بها.", "التوبة: الاعتراف بالذنب، وذلك بالاستغفار أي طلب المغفرة.", "شؤم الخطيئة كان سبب طرد إبليس من الرحمة، وإخراج آدم من الجنة.", "لا تتم حياة للإنسان على غير الأرض، ولا يُدفن بعد موته في غيرها، لدلالة آية «فيها تحيون وفيها تموتون ومنها تُخرجون»."], "k": "«ربنا ظلمنا أنفسنا»… كلمات أبي آدم بعد الزلّة؛ فهل أسرع إليها كما أسرع هو، أم أُكابر كما كابر إبليس؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (101, 7, 26, 36, 'سورة الأعراف ٢٦ – ٣٦', '«يا بني آدم»: لباس التقوى، «خذوا زينتكم عند كل مسجد»، و«قل إنما حرّم ربي الفواحش»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 101) = $j$[{"lbl": "الآيات ٢٦ – ٢٨", "q": "يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿٢٦﴾ يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ ﴿٢٧﴾ وَإِذَا فَعَلُواْ فَٰحِشَةٗ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٢٨﴾", "w": [["وريشاً", "لباس الزينة والحاجة."], ["يواري سوآتكم", "يستر عوراتكم."], ["لباس التقوى", "خير في حفظ العورات والأجسام والعقول والأخلاق."], ["من آيات الله", "دلائل قدرته."], ["لا يفتننّكم", "لا يصرفنّكم عن طاعة الله الموجبة لرضاه ومجاورته في الملكوت الأعلى."], ["أبويكم", "آدم وحواء."], ["قبيله", "جنوده من الجن."], ["فاحشة", "خصلة قبيحة شديدة القبح كالطواف بالبيت عراة."]], "m": "يا بني آدم قد أنزلنا عليكم لباساً يواري سوآتكم وريشاً تتجمّلون به في أعيادكم ومناسباتكم، تذكير للمشركين بنعم الله لعلهم يؤمنون. ولباس التقوى خير لصاحبه من لباس الثياب، لأن المتقي ملتزم بطاعة الله ورسوله، وهما يأمران بستر العورات والحياء والعفة وحسن السمت ونظافة الجسم والثياب، ذلك من آيات الله الدالة على قدرته لعلهم يذكرون فيشكرون. يا بني آدم لا يفتننّكم الشيطان كما أخرج أبويكم من الجنة ينزع عنهما لباسهما ليريهما سوآتهما، إنه يراكم هو وجنوده من حيث لا ترونهم. إنا جعلنا الشياطين أولياء للذين لا يؤمنون، حسب سنته في خلقه، فقلوبهم المظلمة متهيّئة لقبول وساوسهم. ومن برهان هذا الولاء أنهم إذا فعلوا فاحشة احتجّوا بأنهم وجدوا عليها آباءهم والله أمرهم بها، وهي حجة باطلة: ففعل الآباء ليس ديناً ولا شرعاً، وحاشا لله أن يأمر بالفواحش، إنما يأمر بها الشياطين وأولياؤهم، قل إن الله لا يأمر بالفحشاء، أتقولون على الله ما لا تعلمون؟", "h": ["التذكير بنعم الله تعالى المقتضي للشكر عليها بالإيمان والتقوى.", "التحذير من الشيطان وفتنته، لا سيما وأنه يرى الإنسان والإنسان لا يراه.", "القلوب الكافرة هي الآثمة، وبذلك تتم الولاية بين الشياطين والكافرين.", "قبح الفواحش وحرمتها.", "تنزّه الرب تعالى عن الرضا بالفواحش، فضلاً عن الأمر بها."], "k": "«ولباس التقوى ذلك خير»… أعتني بثيابي أمام الناس، فهل أعتني كذلك بلباس التقوى أمام ربي؟"}, {"lbl": "الآيات ٢٩ – ٣١", "q": "قُلۡ أَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ ﴿٢٩﴾ فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ﴿٣٠﴾ ۞يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ﴿٣١﴾", "w": [["القسط", "العدل في القول والحكم والعمل."], ["أقيموا وجوهكم", "أخلصوا العبادة لله واستقبلوا بيته."], ["كما بدأكم تعودون", "كما بدأ خلقكم أول مرة يعيدكم بعد الموت أحياء."], ["أولياء من دون الله", "يوالونهم محبة ونصرة وطاعة من غير الله تعالى."], ["زينتكم", "أي البسوا ثيابكم عند الدخول في الصلاة."], ["ولا تسرفوا", "في أكل ولا شرب، والإسراف: مجاوزة الحد المطلوب في كل شيء."]], "m": "أكذب الله المشركين في دعواهم أنه أمرهم بالفواحش، وقال: قل يا رسولنا: أمر ربي بالقسط، وهو العدل: الإيمان بالله ورسوله وتوحيده في عبادته، لا الشرك وفعل الفواحش والكذب على الله في التحليل والتحريم، وأقيموا وجوهكم عند كل مسجد فأخلصوا له العبادة واستقبلوا بيته الحرام، وادعوه وحده مخلصين له الدين، كما بدأكم تعودون، تذكير بالدار الآخرة، فمن آمن بالجزاء أمكنه الاستقامة طوال الحياة. فريقاً هدى فاهتدوا، وفريقاً حقّ عليهم الضلالة بسبب رغبتهم عن الهداية وموالاتهم أهل الغواية، إنهم اتخذوا الشياطين أولياء من دون الله، ويحسبون لتوغّلهم في الضلال أنهم مهتدون. يا بني آدم خذوا زينتكم عند كل مسجد، فالبسوا ثيابكم عند الطواف بالبيت فلا تطوفوا عراة، وعند الصلاة فلا تصلّوا مكشوفي العورات كما يفعل المشركون، وكلوا مما أحل الله لكم واشربوا، ولا تسرفوا بتحريم ما أحل الله، إنه لا يحب المسرفين، فاطلبوا حبه بالعدل وطاعته وطاعة رسوله.", "h": ["وجوب العدل في القول وفي الحكم.", "وجوب إخلاص العبادة، صلاة كانت أو دعاء، لله تعالى.", "ثبوت القدر.", "وجوب ستر العورة في الصلاة.", "حرمة الإسراف في الأكل والشرب وفي كل شيء."], "k": "«خذوا زينتكم عند كل مسجد»… هل أتهيّأ للوقوف بين يدي ربي كما أتهيّأ للقاء الناس؟"}, {"lbl": "الآيات ٣٢ – ٣٤", "q": "قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٣٢﴾ قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٣٣﴾ وَلِكُلِّ أُمَّةٍ أَجَلٞۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٣٤﴾", "w": [["من حرّم زينة الله", "التحريم: المنع، والزينة: ما يُتزيّن به من ثياب وغيرها."], ["والطيبات", "جمع طيب، وهو الحلال غير المستخبث."], ["خالصة", "لا يشاركهم فيها الكفار لأنهم في النار."], ["الفواحش", "جمع فاحشة، والمراد بها هنا الزنى واللواط، السري كالعلني."], ["والبغي بغير الحق", "الظلم بغير قصاص ومعاقبة بالمثل."], ["وأن تشركوا", "الشرك بالله، وهو عبادة غير الله تعالى."], ["سلطاناً", "الحجة التي تثبت بها الحقوق المختلف فيها أو المتنازع عليها."], ["أجل", "وقت محدّد تنتهي إليه."]], "m": "لما حرّم المشركون الطواف بالثياب، وطافوا عراة بدعوى أنهم لا يطوفون بثياب عصوا الله فيها، أنكر الله عليهم: قل من حرّم زينة الله التي أخرج لعباده من النبات كالقطن والكتان ومعادن الحديد، والطيبات من الرزق كلحوم ما حرّموه من السوائب؟ قل هي للذين آمنوا في الحياة الدنيا بالأصالة، لأنهم يُحسنون العمل والإنتاج، والكفار تبع لهم في ذلك، وخالصة لهم يوم القيامة لا يشاركهم فيها الكفار، كذلك نفصّل الآيات لقوم يعلمون، أما أهل الجهل فمحجوبون بظلمة الكفر ودخان الأهواء. ثم بيّن أصول المحرمات وأمهات الذنوب: قل إنما حرّم ربي الفواحش ما ظهر منها وما بطن، والإثم وهو سائر المعاصي، والبغي وهو الاستطالة على الناس بهضم حقوقهم وأخذ أموالهم وضرب أجسامهم بغير حق، وأن تشركوا بالله ما لم ينزّل به سلطاناً، وأن تقولوا على الله ما لا تعلمون، كتحريم ما لم يحرّم وإيجاب ما لم يوجب. ولكل أمة أجل محدّد يتم هلاكها فيه، لا يستأخرون ساعة ولا يستقدمون، وفيه إشارة إلى أن هلاك الأمم والأفراد يتم بسبب انحرافهم عن منهج الحياة، كالمرء يهلك بشرب السم، فارتكاب أمهات الذنوب يودي بأهلها ما لم يتوبوا.", "h": ["الإنكار الشديد على من يحرّم ما أحل الله من الطيبات، كبعض المتنطّعين.", "المستلذّات من الطعام والشراب والمزيّنات من الثياب وغيرها المؤمنون أولى بها من غيرهم، لأنهم يُحسنون العمل ويبذلون الجهد لاستخراجها والانتفاع بها، فإن قيل: إن أمم الكفر في أوربا وأمريكا هي التي تقدّمت صناعياً، فالجواب: أن المؤمنين صُرفوا عن العلم والعمل بإفساد أعدائهم لعقولهم وعقائدهم، والدليل أنهم لما كانوا كاملين في إيمانهم كانوا أرقى الأمم حضارة وقوة وإنتاجاً، والآية تقول: «لقوم يعلمون»، فإذا حلّ الجهل محل العلم فلا إنتاج ولا اختراع ولا حضارة.", "بيان أصول المفاسد، وهي الفواحش وما ذُكر بعدها إلى «وأن تقولوا على الله ما لا تعلمون».", "ذُكرت هذه المفاسد بطريق التدلّي: آخرها أخطرها، وهكذا أخفّها أولها.", "أجل الأمم كأجل الأفراد، يتم الهلاك عند انتظام المرض كامل الأمة أو أكثر أفرادها، كما يهلك الفرد عندما يستشري المرض في كامل جسمه."], "k": "«وأن تقولوا على الله ما لا تعلمون»… هل أتكلّم في الدين بغير علم، ولو بكلمة «حلال» أو «حرام»؟"}, {"lbl": "الآيتان ٣٥ – ٣٦", "q": "يَٰبَنِيٓ ءَادَمَ إِمَّا يَأۡتِيَنَّكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٣٥﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٣٦﴾", "w": [["إمّا يأتينّكم", "أصل إمّا: إنْ الشرطية وما زائدة لتقوية الكلام، أُدغمت فيها إن."], ["يقصّون عليكم آياتي", "يتلونها عليكم آية بعد آية، مبيّنين لكم ما دلّت عليه من أحكام الله وشرائعه ووعده ووعيده."], ["فمن اتقى", "أي الشرك فلم يشرك، وأصلح نفسه بالأعمال الصالحة."], ["فلا خوف عليهم", "في الدنيا والآخرة."], ["ولا هم يحزنون", "على ما تركوا وراءهم، أو فاتهم الحصول عليه من أمور الدنيا."]], "m": "هذا النداء يجوز أن يكون عاماً لكل بني آدم، نوديت به البشرية على ألسنة رسلها، ويجوز أن يكون خاصاً بمشركي العرب، والمراد بالرسل محمد ﷺ، ذُكر بصيغة الجمع تعظيماً له: إما يأتينّكم رسل منكم من جنسكم يقصّون عليكم آياتي، تحمل العلم بالله وصفاته وبيان محابّه ومساخطه، فمن اتقى الله فترك الشرك، وأصلح ما أفسده قبل العلم من نفسه وخلقه وعقله بالإيمان والعمل الصالح، فلا خوف عليهم ولا هم يحزنون في الحياتين معاً. والذين كذّبوا بآياتنا واستكبروا عن العمل بها كما استكبروا عن الإيمان بها، أولئك البعداء من كل خير أصحاب النار هم فيها خالدون، لا يخرجون منها بحال.", "h": ["قطع حجة بني آدم بإرسال الرسل إليهم.", "أول ما يُبدأ به في باب التقوى الشرك، بأن يتخلّى عنه الإنسان المؤمن أولاً.", "الإصلاح يكون بالأعمال الصالحة التي شرعها الله مزكّية للنفوس مطهّرة لها.", "التكذيب كالاستكبار، كلاهما مانع من التقوى والعمل الصالح، ولذا كان أصحابهما أصحاب النار."], "k": "«فمن اتقى وأصلح»… ما الذي أفسدته في نفسي من قبل، وأحتاج أن أصلحه اليوم؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 101;
insert into public.tdb_cards(topic, i, body) select 101, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٢٦ – ٢٨", "q": "يَٰبَنِيٓ ءَادَمَ قَدۡ أَنزَلۡنَا عَلَيۡكُمۡ لِبَاسٗا يُوَٰرِي سَوۡءَٰتِكُمۡ وَرِيشٗاۖ وَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ ذَٰلِكَ مِنۡ ءَايَٰتِ ٱللَّهِ لَعَلَّهُمۡ يَذَّكَّرُونَ ﴿٢٦﴾ يَٰبَنِيٓ ءَادَمَ لَا يَفۡتِنَنَّكُمُ ٱلشَّيۡطَٰنُ كَمَآ أَخۡرَجَ أَبَوَيۡكُم مِّنَ ٱلۡجَنَّةِ يَنزِعُ عَنۡهُمَا لِبَاسَهُمَا لِيُرِيَهُمَا سَوۡءَٰتِهِمَآۚ إِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ إِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ ﴿٢٧﴾ وَإِذَا فَعَلُواْ فَٰحِشَةٗ قَالُواْ وَجَدۡنَا عَلَيۡهَآ ءَابَآءَنَا وَٱللَّهُ أَمَرَنَا بِهَاۗ قُلۡ إِنَّ ٱللَّهَ لَا يَأۡمُرُ بِٱلۡفَحۡشَآءِۖ أَتَقُولُونَ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٢٨﴾", "w": [["وريشاً", "لباس الزينة والحاجة."], ["يواري سوآتكم", "يستر عوراتكم."], ["لباس التقوى", "خير في حفظ العورات والأجسام والعقول والأخلاق."], ["من آيات الله", "دلائل قدرته."], ["لا يفتننّكم", "لا يصرفنّكم عن طاعة الله الموجبة لرضاه ومجاورته في الملكوت الأعلى."], ["أبويكم", "آدم وحواء."], ["قبيله", "جنوده من الجن."], ["فاحشة", "خصلة قبيحة شديدة القبح كالطواف بالبيت عراة."]], "m": "يا بني آدم قد أنزلنا عليكم لباساً يواري سوآتكم وريشاً تتجمّلون به في أعيادكم ومناسباتكم، تذكير للمشركين بنعم الله لعلهم يؤمنون. ولباس التقوى خير لصاحبه من لباس الثياب، لأن المتقي ملتزم بطاعة الله ورسوله، وهما يأمران بستر العورات والحياء والعفة وحسن السمت ونظافة الجسم والثياب، ذلك من آيات الله الدالة على قدرته لعلهم يذكرون فيشكرون. يا بني آدم لا يفتننّكم الشيطان كما أخرج أبويكم من الجنة ينزع عنهما لباسهما ليريهما سوآتهما، إنه يراكم هو وجنوده من حيث لا ترونهم. إنا جعلنا الشياطين أولياء للذين لا يؤمنون، حسب سنته في خلقه، فقلوبهم المظلمة متهيّئة لقبول وساوسهم. ومن برهان هذا الولاء أنهم إذا فعلوا فاحشة احتجّوا بأنهم وجدوا عليها آباءهم والله أمرهم بها، وهي حجة باطلة: ففعل الآباء ليس ديناً ولا شرعاً، وحاشا لله أن يأمر بالفواحش، إنما يأمر بها الشياطين وأولياؤهم، قل إن الله لا يأمر بالفحشاء، أتقولون على الله ما لا تعلمون؟", "h": ["التذكير بنعم الله تعالى المقتضي للشكر عليها بالإيمان والتقوى.", "التحذير من الشيطان وفتنته، لا سيما وأنه يرى الإنسان والإنسان لا يراه.", "القلوب الكافرة هي الآثمة، وبذلك تتم الولاية بين الشياطين والكافرين.", "قبح الفواحش وحرمتها.", "تنزّه الرب تعالى عن الرضا بالفواحش، فضلاً عن الأمر بها."], "k": "«ولباس التقوى ذلك خير»… أعتني بثيابي أمام الناس، فهل أعتني كذلك بلباس التقوى أمام ربي؟"}, {"lbl": "الآيات ٢٩ – ٣١", "q": "قُلۡ أَمَرَ رَبِّي بِٱلۡقِسۡطِۖ وَأَقِيمُواْ وُجُوهَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَٱدۡعُوهُ مُخۡلِصِينَ لَهُ ٱلدِّينَۚ كَمَا بَدَأَكُمۡ تَعُودُونَ ﴿٢٩﴾ فَرِيقًا هَدَىٰ وَفَرِيقًا حَقَّ عَلَيۡهِمُ ٱلضَّلَٰلَةُۚ إِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ﴿٣٠﴾ ۞يَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ﴿٣١﴾", "w": [["القسط", "العدل في القول والحكم والعمل."], ["أقيموا وجوهكم", "أخلصوا العبادة لله واستقبلوا بيته."], ["كما بدأكم تعودون", "كما بدأ خلقكم أول مرة يعيدكم بعد الموت أحياء."], ["أولياء من دون الله", "يوالونهم محبة ونصرة وطاعة من غير الله تعالى."], ["زينتكم", "أي البسوا ثيابكم عند الدخول في الصلاة."], ["ولا تسرفوا", "في أكل ولا شرب، والإسراف: مجاوزة الحد المطلوب في كل شيء."]], "m": "أكذب الله المشركين في دعواهم أنه أمرهم بالفواحش، وقال: قل يا رسولنا: أمر ربي بالقسط، وهو العدل: الإيمان بالله ورسوله وتوحيده في عبادته، لا الشرك وفعل الفواحش والكذب على الله في التحليل والتحريم، وأقيموا وجوهكم عند كل مسجد فأخلصوا له العبادة واستقبلوا بيته الحرام، وادعوه وحده مخلصين له الدين، كما بدأكم تعودون، تذكير بالدار الآخرة، فمن آمن بالجزاء أمكنه الاستقامة طوال الحياة. فريقاً هدى فاهتدوا، وفريقاً حقّ عليهم الضلالة بسبب رغبتهم عن الهداية وموالاتهم أهل الغواية، إنهم اتخذوا الشياطين أولياء من دون الله، ويحسبون لتوغّلهم في الضلال أنهم مهتدون. يا بني آدم خذوا زينتكم عند كل مسجد، فالبسوا ثيابكم عند الطواف بالبيت فلا تطوفوا عراة، وعند الصلاة فلا تصلّوا مكشوفي العورات كما يفعل المشركون، وكلوا مما أحل الله لكم واشربوا، ولا تسرفوا بتحريم ما أحل الله، إنه لا يحب المسرفين، فاطلبوا حبه بالعدل وطاعته وطاعة رسوله.", "h": ["وجوب العدل في القول وفي الحكم.", "وجوب إخلاص العبادة، صلاة كانت أو دعاء، لله تعالى.", "ثبوت القدر.", "وجوب ستر العورة في الصلاة.", "حرمة الإسراف في الأكل والشرب وفي كل شيء."], "k": "«خذوا زينتكم عند كل مسجد»… هل أتهيّأ للوقوف بين يدي ربي كما أتهيّأ للقاء الناس؟"}, {"lbl": "الآيات ٣٢ – ٣٤", "q": "قُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ﴿٣٢﴾ قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٣٣﴾ وَلِكُلِّ أُمَّةٍ أَجَلٞۖ فَإِذَا جَآءَ أَجَلُهُمۡ لَا يَسۡتَأۡخِرُونَ سَاعَةٗ وَلَا يَسۡتَقۡدِمُونَ ﴿٣٤﴾", "w": [["من حرّم زينة الله", "التحريم: المنع، والزينة: ما يُتزيّن به من ثياب وغيرها."], ["والطيبات", "جمع طيب، وهو الحلال غير المستخبث."], ["خالصة", "لا يشاركهم فيها الكفار لأنهم في النار."], ["الفواحش", "جمع فاحشة، والمراد بها هنا الزنى واللواط، السري كالعلني."], ["والبغي بغير الحق", "الظلم بغير قصاص ومعاقبة بالمثل."], ["وأن تشركوا", "الشرك بالله، وهو عبادة غير الله تعالى."], ["سلطاناً", "الحجة التي تثبت بها الحقوق المختلف فيها أو المتنازع عليها."], ["أجل", "وقت محدّد تنتهي إليه."]], "m": "لما حرّم المشركون الطواف بالثياب، وطافوا عراة بدعوى أنهم لا يطوفون بثياب عصوا الله فيها، أنكر الله عليهم: قل من حرّم زينة الله التي أخرج لعباده من النبات كالقطن والكتان ومعادن الحديد، والطيبات من الرزق كلحوم ما حرّموه من السوائب؟ قل هي للذين آمنوا في الحياة الدنيا بالأصالة، لأنهم يُحسنون العمل والإنتاج، والكفار تبع لهم في ذلك، وخالصة لهم يوم القيامة لا يشاركهم فيها الكفار، كذلك نفصّل الآيات لقوم يعلمون، أما أهل الجهل فمحجوبون بظلمة الكفر ودخان الأهواء. ثم بيّن أصول المحرمات وأمهات الذنوب: قل إنما حرّم ربي الفواحش ما ظهر منها وما بطن، والإثم وهو سائر المعاصي، والبغي وهو الاستطالة على الناس بهضم حقوقهم وأخذ أموالهم وضرب أجسامهم بغير حق، وأن تشركوا بالله ما لم ينزّل به سلطاناً، وأن تقولوا على الله ما لا تعلمون، كتحريم ما لم يحرّم وإيجاب ما لم يوجب. ولكل أمة أجل محدّد يتم هلاكها فيه، لا يستأخرون ساعة ولا يستقدمون، وفيه إشارة إلى أن هلاك الأمم والأفراد يتم بسبب انحرافهم عن منهج الحياة، كالمرء يهلك بشرب السم، فارتكاب أمهات الذنوب يودي بأهلها ما لم يتوبوا.", "h": ["الإنكار الشديد على من يحرّم ما أحل الله من الطيبات، كبعض المتنطّعين.", "المستلذّات من الطعام والشراب والمزيّنات من الثياب وغيرها المؤمنون أولى بها من غيرهم، لأنهم يُحسنون العمل ويبذلون الجهد لاستخراجها والانتفاع بها، فإن قيل: إن أمم الكفر في أوربا وأمريكا هي التي تقدّمت صناعياً، فالجواب: أن المؤمنين صُرفوا عن العلم والعمل بإفساد أعدائهم لعقولهم وعقائدهم، والدليل أنهم لما كانوا كاملين في إيمانهم كانوا أرقى الأمم حضارة وقوة وإنتاجاً، والآية تقول: «لقوم يعلمون»، فإذا حلّ الجهل محل العلم فلا إنتاج ولا اختراع ولا حضارة.", "بيان أصول المفاسد، وهي الفواحش وما ذُكر بعدها إلى «وأن تقولوا على الله ما لا تعلمون».", "ذُكرت هذه المفاسد بطريق التدلّي: آخرها أخطرها، وهكذا أخفّها أولها.", "أجل الأمم كأجل الأفراد، يتم الهلاك عند انتظام المرض كامل الأمة أو أكثر أفرادها، كما يهلك الفرد عندما يستشري المرض في كامل جسمه."], "k": "«وأن تقولوا على الله ما لا تعلمون»… هل أتكلّم في الدين بغير علم، ولو بكلمة «حلال» أو «حرام»؟"}, {"lbl": "الآيتان ٣٥ – ٣٦", "q": "يَٰبَنِيٓ ءَادَمَ إِمَّا يَأۡتِيَنَّكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي فَمَنِ ٱتَّقَىٰ وَأَصۡلَحَ فَلَا خَوۡفٌ عَلَيۡهِمۡ وَلَا هُمۡ يَحۡزَنُونَ ﴿٣٥﴾ وَٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٣٦﴾", "w": [["إمّا يأتينّكم", "أصل إمّا: إنْ الشرطية وما زائدة لتقوية الكلام، أُدغمت فيها إن."], ["يقصّون عليكم آياتي", "يتلونها عليكم آية بعد آية، مبيّنين لكم ما دلّت عليه من أحكام الله وشرائعه ووعده ووعيده."], ["فمن اتقى", "أي الشرك فلم يشرك، وأصلح نفسه بالأعمال الصالحة."], ["فلا خوف عليهم", "في الدنيا والآخرة."], ["ولا هم يحزنون", "على ما تركوا وراءهم، أو فاتهم الحصول عليه من أمور الدنيا."]], "m": "هذا النداء يجوز أن يكون عاماً لكل بني آدم، نوديت به البشرية على ألسنة رسلها، ويجوز أن يكون خاصاً بمشركي العرب، والمراد بالرسل محمد ﷺ، ذُكر بصيغة الجمع تعظيماً له: إما يأتينّكم رسل منكم من جنسكم يقصّون عليكم آياتي، تحمل العلم بالله وصفاته وبيان محابّه ومساخطه، فمن اتقى الله فترك الشرك، وأصلح ما أفسده قبل العلم من نفسه وخلقه وعقله بالإيمان والعمل الصالح، فلا خوف عليهم ولا هم يحزنون في الحياتين معاً. والذين كذّبوا بآياتنا واستكبروا عن العمل بها كما استكبروا عن الإيمان بها، أولئك البعداء من كل خير أصحاب النار هم فيها خالدون، لا يخرجون منها بحال.", "h": ["قطع حجة بني آدم بإرسال الرسل إليهم.", "أول ما يُبدأ به في باب التقوى الشرك، بأن يتخلّى عنه الإنسان المؤمن أولاً.", "الإصلاح يكون بالأعمال الصالحة التي شرعها الله مزكّية للنفوس مطهّرة لها.", "التكذيب كالاستكبار، كلاهما مانع من التقوى والعمل الصالح، ولذا كان أصحابهما أصحاب النار."], "k": "«فمن اتقى وأصلح»… ما الذي أفسدته في نفسي من قبل، وأحتاج أن أصلحه اليوم؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (102, 7, 37, 51, 'سورة الأعراف ٣٧ – ٥١', '«حتى يلج الجمل في سم الخياط»، «ونزعنا ما في صدورهم من غل»، وأصحاب الأعراف', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 102) = $j$[{"lbl": "الآيات ٣٧ – ٤١", "q": "فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ أُوْلَـٰٓئِكَ يَنَالُهُمۡ نَصِيبُهُم مِّنَ ٱلۡكِتَٰبِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَالُوٓاْ أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ﴿٣٧﴾ قَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ﴿٣٨﴾ وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلٖ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ ﴿٣٩﴾ إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ ﴿٤٠﴾ لَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٤١﴾", "w": [["فمن أظلم", "الظلم: وضع الشيء في غير موضعه، ولذا المشرك ظالم لأنه وضع العبادة في غير موضعها، حيث عبد بها من لا يستحقها."], ["نصيبهم", "ما قُدّر لهم في كتاب المقادير."], ["رسلنا", "المراد بهم ملك الموت وأعوانه."], ["قالوا ضلّوا عنا", "غابوا عنا فلم نرهم ولم نجدهم."], ["في أمم", "في جملة أمم."], ["ادّاركوا", "تداركوا ولحق بعضهم بعضاً حتى دخلوها كلهم."], ["أخراهم لأولاهم", "الأتباع قالوا للرؤساء في الضلالة، وهم المتبوعون."], ["تكسبون", "من الظلم والشر والفساد."], ["يلج الجمل في سم الخياط", "يدخل الجمل في ثقب الإبرة."], ["المجرمين", "الذين أجرموا على أنفسهم فأفسدوها بالشرك والمعاصي."], ["مهاد", "فراش يمتهدونه من النار."], ["غواش", "أغطية يتغطّون بها من النار كذلك."]], "m": "لا أظلم ممن افترى على الله كذباً، فقال: اتخذ ولداً، أو أمر بالفواحش، أو حرّم كذا وهو لم يحرّمه، أو كذّب بآياته. أولئك ينالهم نصيبهم مما كُتب لهم في اللوح المحفوظ، حتى إذا جاءتهم رسلنا، ملك الموت وأعوانه، يتوفّونهم قالوا: أين ما كنتم تدعون من دون الله؟ قالوا: ضلّوا عنا، وشهدوا على أنفسهم أنهم كانوا كافرين. ويوم القيامة يقال لهم: ادخلوا في أمم قد خلت من قبلكم من الجن والإنس في النار، كلما دخلت أمة لعنت أختها، حتى إذا ادّاركوا فيها جميعاً قالت أخراهم لأولاهم: ربنا هؤلاء أضلّونا فآتهم عذاباً مضاعفاً من النار، قال: لكلٍّ ضعف ولكن لا تعلمون، إذ الدار دار عذاب يتضاعف على كل من فيها، وقالت أولاهم لأخراهم: فما كان لكم علينا من فضل، فذوقوا العذاب بما كنتم تكسبون. إن الذين كذّبوا بآياتنا واستكبروا عنها فلم يؤمنوا ولم يعملوا الصالحات، إذا مات أحدهم وعرجت الملائكة بروحه لا تُفتّح له أبواب السماء، ولا يدخلون الجنة حتى يلج الجمل في سم الخياط، فعلّق دخولهم على مستحيل، والمعلّق على مستحيل مستحيل، وكذلك نجزي المجرمين، لهم من جهنم مهاد ومن فوقهم أغطية من النار، وكذلك نجزي الظالمين لأنفسهم بأوضار الذنوب.", "h": ["شر الظلم ما كان كذباً على الله وتكذيباً بشرائعه.", "تقرير فتنة القبر وعذابه.", "لعن أهل النار بعضهم بعضاً حنقاً على بعضهم بعضاً، إذ كان كل واحد سبباً في عذاب الآخر.", "بيان جزاء المكذّبين بآيات الله والمستكبرين عنها، وهو الحرمان من دخول الجنة، وكذلك المجرمون والظالمون."], "k": "«ربنا هؤلاء أضلّونا»… من أتبعه اليوم في ديني ودنياي، وهل سأحمده يوم القيامة أم ألعنه؟"}, {"lbl": "الآيتان ٤٢ – ٤٣", "q": "وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٤٢﴾ وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٤٣﴾", "w": [["إلا وسعها", "طاقتها، وما تتحمّله وتقدر عليه من العمل."], ["ونزعنا", "أقلعنا وأخرجنا."], ["من غل", "من حقد وعداوة."], ["هدانا لهذا", "للعمل الصالح في الدنيا الذي هذا جزاؤه، وهو الجنة."], ["بما كنتم تعملون", "بسبب أعمالكم الصالحة من صلاة وصيام وصدقات وجهاد."]], "m": "لما ذكر جزاء أهل التكذيب والاستكبار ذكر جزاء أهل الإيمان والعمل الصالح: والذين آمنوا وعملوا الصالحات، ولما كان من العمل الشاق الذي لا يطاق قال: لا نكلّف نفساً إلا ما تقدر عليه، أولئك أصحاب الجنة هم فيها خالدون. وطهّرهم باطناً، فنزع ما في صدورهم من غل على بعضهم بعضاً، تجري من تحت قصورهم الأنهار، وقالوا شاكرين: الحمد لله الذي هدانا لعمل صالح هذا جزاؤه، وقرّروا أن هدايتهم لم يكونوا ليحصلوا عليها لولا أن الله هداهم: وما كنا لنهتدي لولا أن هدانا الله، لقد جاءت رسل ربنا بالحق، فها هم أهل الكفر في النار، ونحن أهل الإيمان في نعيم الجنة، فصدقت الرسل فيما أخبرت به من وعد ووعيد. ونودوا: أن تلكم الجنة أُورثتموها بما كنتم تعملون.", "h": ["الإيمان والعمل الصالح موجبان لدخول الجنة، مقتضيان للكرامة في الدارين.", "لا مشقة لا تُحتمل في الدين الصحيح الذي جاءت به الرسل، إلا ما كان عقوبة.", "لا عداوة ولا حسد في الجنة.", "الهداية هبة من الله، فلا تُطلب إلا منه، ولا يُحصل عليها إلا بطلبها منه تعالى.", "صدقت الرسل فيما أخبرت به من شأن الغيب وغيره."], "k": "«ونزعنا ما في صدورهم من غل»… هل أبدأ من الآن بتطهير قلبي من غلّ على أحد؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ ﴿٤٤﴾ ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ ﴿٤٥﴾ وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ ﴿٤٦﴾ ۞وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤٧﴾", "w": [["فأذّن مؤذّن", "أعلن بأعلى صوته أن لعنة الله على الظالمين."], ["لعنة الله", "أمره بطرد الظالمين من الرحمة إلى العذاب."], ["يصدّون عن سبيل الله", "سبيل الله هي الإسلام، والصد: الصرف."], ["ويبغونها عوجاً", "يطلبون الشريعة أن تميل مع ميولهم وشهواتهم فتخدم أغراضهم."], ["وبينهما حجاب", "بين أهل الجنة وأهل النار حاجز فاصل، وهو سور الأعراف."], ["وعلى الأعراف", "سور بين الجنة والنار."], ["يعرفون كلاً بسيماهم", "يعرفون كلاً من أهل الجنة وأهل النار بعلاماتهم."], ["صُرفت أبصارهم", "نظروا إلى الجهة التي فيها أصحاب النار."]], "m": "نادى أصحاب الجنة أصحاب النار: إنا قد وجدنا ما وعدنا ربنا من الجنة ونعيمها حقاً، فهل وجدتم ما وعد ربكم من النار وعذابها حقاً؟ قالوا: نعم. فأذّن مؤذّن بينهم: أن لعنة الله على الظالمين، الذين يصدّون عن سبيل الله، الإسلام الموصل إلى رضاه والجنة، ويريدونها معوجّة تدور معهم في شرورهم وشهواتهم، وهم بالآخرة كافرون. وبينهما حجاب، حاجز فاصل، وهو مكان مرتفع، عليه رجال من بني آدم استوت حسناتهم وسيئاتهم، فحُبسوا هناك حتى يُقضى بين أهل الموقف فيُحكم فيهم بدخول الجنة إن شاء الله، يعرفون أهل الجنة ببياض الوجوه ونضرة النعيم، وأهل النار بسواد الوجوه وزرقة العيون. ونادوا أصحاب الجنة: سلام عليكم، لم يدخلوها وهم يطمعون، وإذا صُرفت أبصارهم تلقاء أصحاب النار فرأوا وجوههم مسودّة يكتنفهم العذاب، قالوا: ربنا لا تجعلنا مع القوم الظالمين.", "h": ["وجود اتصال كامل بين أهل الجنة وأهل النار متى أراد أحدهم ذلك، بحيث إذا أراد من في الجنة أن ينظر إلى من في النار ويخاطبه تمّ له ذلك.", "يجوز إطلاق لفظ الوعد على الوعيد للمشاكلة أو التهكم، كما في هذه الآيات.", "التنديد بالصد عن سبيل الله، والظلم، والكفر بالآخرة، وهي أسباب الشقاء في الدار الآخرة.", "تقرير مبدأ: ثقل الحسنات يُنجي وخفّتها تُردي، ومن استوت حسناته وسيئاته ينجو آخر من ينجو من دخول النار.", "مشروعية الطمع إذا كان مقتضاه موجوداً."], "k": "«ويبغونها عوجاً»… هل أطلب من الدين أن يميل مع هواي، أم أُميل هواي معه؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ ﴿٤٨﴾ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ ﴿٤٩﴾ وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ﴿٥٠﴾ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوٗا وَلَعِبٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿٥١﴾", "w": [["بسيماهم", "السيما: العلامة الدالة على من هي فيه."], ["جمعكم", "للمال وللرجال كالجيوش."], ["أهؤلاء", "إشارة إلى ضعفاء المسلمين وهم في الجنة."], ["أو مما رزقكم الله", "أي من الطعام والشراب."]], "m": "نادى أصحاب الأعراف رجالاً من أهل النار يعرفونهم بسيماهم من سواد الوجوه وزرقة العيون: ما أغنى عنكم جمعكم للأموال والرجال، وما كنتم تستكبرون على الحق، وها أنتم في أشد العذاب؟ ثم يشيرون إلى ضعفة المسلمين الذين كانوا يسخرون منهم ويضربونهم ويهينونهم في الدنيا: أهؤلاء الذين أقسمتم لا ينالهم الله برحمة؟ ثم يقال لأصحاب الأعراف: ادخلوا الجنة لا خوف عليكم ولا أنتم تحزنون. ونادى أصحاب النار أصحاب الجنة لشدة عطشهم وجوعهم: أن أفيضوا علينا من الماء أو مما رزقكم الله من الطعام، قالوا: إن الله حرّمهما على الكافرين فلا ينالونهما بحال. ثم وصف الكافرين ليعرض جرائمهم عظة لقريش ولسائر الناس: الذين اتخذوا دينهم لهواً ولعباً وغرّتهم الحياة الدنيا، فاليوم ننساهم فنتركهم في عذابهم كما نسوا لقاء يومهم هذا فلم يعملوا له، وبما كانوا بآياتنا يجحدون.", "h": ["عدم إغناء المال والرجال أيّ إغناء لمن مات كافراً مشركاً من أهل الظلم والفساد.", "بشرى الضعفة من المسلمين بدخول الجنة وسعادتهم فيها.", "تحريم اتخاذ شيء من الدين لهواً ولعباً.", "التحذير من الاغترار بالدنيا حتى ينسى العبد آخرته، فلم يُعدّ لها ما ينفعه فيها من الإيمان وصالح الأعمال."], "k": "«فاليوم ننساهم كما نسوا لقاء يومهم هذا»… كم مرة نسيت ذلك اليوم في زحمة يومي؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 102;
insert into public.tdb_cards(topic, i, body) select 102, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٣٧ – ٤١", "q": "فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا أَوۡ كَذَّبَ بِـَٔايَٰتِهِۦٓۚ أُوْلَـٰٓئِكَ يَنَالُهُمۡ نَصِيبُهُم مِّنَ ٱلۡكِتَٰبِۖ حَتَّىٰٓ إِذَا جَآءَتۡهُمۡ رُسُلُنَا يَتَوَفَّوۡنَهُمۡ قَالُوٓاْ أَيۡنَ مَا كُنتُمۡ تَدۡعُونَ مِن دُونِ ٱللَّهِۖ قَالُواْ ضَلُّواْ عَنَّا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ﴿٣٧﴾ قَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَـٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ﴿٣٨﴾ وَقَالَتۡ أُولَىٰهُمۡ لِأُخۡرَىٰهُمۡ فَمَا كَانَ لَكُمۡ عَلَيۡنَا مِن فَضۡلٖ فَذُوقُواْ ٱلۡعَذَابَ بِمَا كُنتُمۡ تَكۡسِبُونَ ﴿٣٩﴾ إِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ ﴿٤٠﴾ لَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّـٰلِمِينَ ﴿٤١﴾", "w": [["فمن أظلم", "الظلم: وضع الشيء في غير موضعه، ولذا المشرك ظالم لأنه وضع العبادة في غير موضعها، حيث عبد بها من لا يستحقها."], ["نصيبهم", "ما قُدّر لهم في كتاب المقادير."], ["رسلنا", "المراد بهم ملك الموت وأعوانه."], ["قالوا ضلّوا عنا", "غابوا عنا فلم نرهم ولم نجدهم."], ["في أمم", "في جملة أمم."], ["ادّاركوا", "تداركوا ولحق بعضهم بعضاً حتى دخلوها كلهم."], ["أخراهم لأولاهم", "الأتباع قالوا للرؤساء في الضلالة، وهم المتبوعون."], ["تكسبون", "من الظلم والشر والفساد."], ["يلج الجمل في سم الخياط", "يدخل الجمل في ثقب الإبرة."], ["المجرمين", "الذين أجرموا على أنفسهم فأفسدوها بالشرك والمعاصي."], ["مهاد", "فراش يمتهدونه من النار."], ["غواش", "أغطية يتغطّون بها من النار كذلك."]], "m": "لا أظلم ممن افترى على الله كذباً، فقال: اتخذ ولداً، أو أمر بالفواحش، أو حرّم كذا وهو لم يحرّمه، أو كذّب بآياته. أولئك ينالهم نصيبهم مما كُتب لهم في اللوح المحفوظ، حتى إذا جاءتهم رسلنا، ملك الموت وأعوانه، يتوفّونهم قالوا: أين ما كنتم تدعون من دون الله؟ قالوا: ضلّوا عنا، وشهدوا على أنفسهم أنهم كانوا كافرين. ويوم القيامة يقال لهم: ادخلوا في أمم قد خلت من قبلكم من الجن والإنس في النار، كلما دخلت أمة لعنت أختها، حتى إذا ادّاركوا فيها جميعاً قالت أخراهم لأولاهم: ربنا هؤلاء أضلّونا فآتهم عذاباً مضاعفاً من النار، قال: لكلٍّ ضعف ولكن لا تعلمون، إذ الدار دار عذاب يتضاعف على كل من فيها، وقالت أولاهم لأخراهم: فما كان لكم علينا من فضل، فذوقوا العذاب بما كنتم تكسبون. إن الذين كذّبوا بآياتنا واستكبروا عنها فلم يؤمنوا ولم يعملوا الصالحات، إذا مات أحدهم وعرجت الملائكة بروحه لا تُفتّح له أبواب السماء، ولا يدخلون الجنة حتى يلج الجمل في سم الخياط، فعلّق دخولهم على مستحيل، والمعلّق على مستحيل مستحيل، وكذلك نجزي المجرمين، لهم من جهنم مهاد ومن فوقهم أغطية من النار، وكذلك نجزي الظالمين لأنفسهم بأوضار الذنوب.", "h": ["شر الظلم ما كان كذباً على الله وتكذيباً بشرائعه.", "تقرير فتنة القبر وعذابه.", "لعن أهل النار بعضهم بعضاً حنقاً على بعضهم بعضاً، إذ كان كل واحد سبباً في عذاب الآخر.", "بيان جزاء المكذّبين بآيات الله والمستكبرين عنها، وهو الحرمان من دخول الجنة، وكذلك المجرمون والظالمون."], "k": "«ربنا هؤلاء أضلّونا»… من أتبعه اليوم في ديني ودنياي، وهل سأحمده يوم القيامة أم ألعنه؟"}, {"lbl": "الآيتان ٤٢ – ٤٣", "q": "وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّـٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ أُوْلَـٰٓئِكَ أَصۡحَٰبُ ٱلۡجَنَّةِۖ هُمۡ فِيهَا خَٰلِدُونَ ﴿٤٢﴾ وَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ وَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ لَقَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّۖ وَنُودُوٓاْ أَن تِلۡكُمُ ٱلۡجَنَّةُ أُورِثۡتُمُوهَا بِمَا كُنتُمۡ تَعۡمَلُونَ ﴿٤٣﴾", "w": [["إلا وسعها", "طاقتها، وما تتحمّله وتقدر عليه من العمل."], ["ونزعنا", "أقلعنا وأخرجنا."], ["من غل", "من حقد وعداوة."], ["هدانا لهذا", "للعمل الصالح في الدنيا الذي هذا جزاؤه، وهو الجنة."], ["بما كنتم تعملون", "بسبب أعمالكم الصالحة من صلاة وصيام وصدقات وجهاد."]], "m": "لما ذكر جزاء أهل التكذيب والاستكبار ذكر جزاء أهل الإيمان والعمل الصالح: والذين آمنوا وعملوا الصالحات، ولما كان من العمل الشاق الذي لا يطاق قال: لا نكلّف نفساً إلا ما تقدر عليه، أولئك أصحاب الجنة هم فيها خالدون. وطهّرهم باطناً، فنزع ما في صدورهم من غل على بعضهم بعضاً، تجري من تحت قصورهم الأنهار، وقالوا شاكرين: الحمد لله الذي هدانا لعمل صالح هذا جزاؤه، وقرّروا أن هدايتهم لم يكونوا ليحصلوا عليها لولا أن الله هداهم: وما كنا لنهتدي لولا أن هدانا الله، لقد جاءت رسل ربنا بالحق، فها هم أهل الكفر في النار، ونحن أهل الإيمان في نعيم الجنة، فصدقت الرسل فيما أخبرت به من وعد ووعيد. ونودوا: أن تلكم الجنة أُورثتموها بما كنتم تعملون.", "h": ["الإيمان والعمل الصالح موجبان لدخول الجنة، مقتضيان للكرامة في الدارين.", "لا مشقة لا تُحتمل في الدين الصحيح الذي جاءت به الرسل، إلا ما كان عقوبة.", "لا عداوة ولا حسد في الجنة.", "الهداية هبة من الله، فلا تُطلب إلا منه، ولا يُحصل عليها إلا بطلبها منه تعالى.", "صدقت الرسل فيما أخبرت به من شأن الغيب وغيره."], "k": "«ونزعنا ما في صدورهم من غل»… هل أبدأ من الآن بتطهير قلبي من غلّ على أحد؟"}, {"lbl": "الآيات ٤٤ – ٤٧", "q": "وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّـٰلِمِينَ ﴿٤٤﴾ ٱلَّذِينَ يَصُدُّونَ عَن سَبِيلِ ٱللَّهِ وَيَبۡغُونَهَا عِوَجٗا وَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ ﴿٤٥﴾ وَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ ﴿٤٦﴾ ۞وَإِذَا صُرِفَتۡ أَبۡصَٰرُهُمۡ تِلۡقَآءَ أَصۡحَٰبِ ٱلنَّارِ قَالُواْ رَبَّنَا لَا تَجۡعَلۡنَا مَعَ ٱلۡقَوۡمِ ٱلظَّـٰلِمِينَ ﴿٤٧﴾", "w": [["فأذّن مؤذّن", "أعلن بأعلى صوته أن لعنة الله على الظالمين."], ["لعنة الله", "أمره بطرد الظالمين من الرحمة إلى العذاب."], ["يصدّون عن سبيل الله", "سبيل الله هي الإسلام، والصد: الصرف."], ["ويبغونها عوجاً", "يطلبون الشريعة أن تميل مع ميولهم وشهواتهم فتخدم أغراضهم."], ["وبينهما حجاب", "بين أهل الجنة وأهل النار حاجز فاصل، وهو سور الأعراف."], ["وعلى الأعراف", "سور بين الجنة والنار."], ["يعرفون كلاً بسيماهم", "يعرفون كلاً من أهل الجنة وأهل النار بعلاماتهم."], ["صُرفت أبصارهم", "نظروا إلى الجهة التي فيها أصحاب النار."]], "m": "نادى أصحاب الجنة أصحاب النار: إنا قد وجدنا ما وعدنا ربنا من الجنة ونعيمها حقاً، فهل وجدتم ما وعد ربكم من النار وعذابها حقاً؟ قالوا: نعم. فأذّن مؤذّن بينهم: أن لعنة الله على الظالمين، الذين يصدّون عن سبيل الله، الإسلام الموصل إلى رضاه والجنة، ويريدونها معوجّة تدور معهم في شرورهم وشهواتهم، وهم بالآخرة كافرون. وبينهما حجاب، حاجز فاصل، وهو مكان مرتفع، عليه رجال من بني آدم استوت حسناتهم وسيئاتهم، فحُبسوا هناك حتى يُقضى بين أهل الموقف فيُحكم فيهم بدخول الجنة إن شاء الله، يعرفون أهل الجنة ببياض الوجوه ونضرة النعيم، وأهل النار بسواد الوجوه وزرقة العيون. ونادوا أصحاب الجنة: سلام عليكم، لم يدخلوها وهم يطمعون، وإذا صُرفت أبصارهم تلقاء أصحاب النار فرأوا وجوههم مسودّة يكتنفهم العذاب، قالوا: ربنا لا تجعلنا مع القوم الظالمين.", "h": ["وجود اتصال كامل بين أهل الجنة وأهل النار متى أراد أحدهم ذلك، بحيث إذا أراد من في الجنة أن ينظر إلى من في النار ويخاطبه تمّ له ذلك.", "يجوز إطلاق لفظ الوعد على الوعيد للمشاكلة أو التهكم، كما في هذه الآيات.", "التنديد بالصد عن سبيل الله، والظلم، والكفر بالآخرة، وهي أسباب الشقاء في الدار الآخرة.", "تقرير مبدأ: ثقل الحسنات يُنجي وخفّتها تُردي، ومن استوت حسناته وسيئاته ينجو آخر من ينجو من دخول النار.", "مشروعية الطمع إذا كان مقتضاه موجوداً."], "k": "«ويبغونها عوجاً»… هل أطلب من الدين أن يميل مع هواي، أم أُميل هواي معه؟"}, {"lbl": "الآيات ٤٨ – ٥١", "q": "وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ ﴿٤٨﴾ أَهَـٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ ٱدۡخُلُواْ ٱلۡجَنَّةَ لَا خَوۡفٌ عَلَيۡكُمۡ وَلَآ أَنتُمۡ تَحۡزَنُونَ ﴿٤٩﴾ وَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ﴿٥٠﴾ ٱلَّذِينَ ٱتَّخَذُواْ دِينَهُمۡ لَهۡوٗا وَلَعِبٗا وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَاۚ فَٱلۡيَوۡمَ نَنسَىٰهُمۡ كَمَا نَسُواْ لِقَآءَ يَوۡمِهِمۡ هَٰذَا وَمَا كَانُواْ بِـَٔايَٰتِنَا يَجۡحَدُونَ ﴿٥١﴾", "w": [["بسيماهم", "السيما: العلامة الدالة على من هي فيه."], ["جمعكم", "للمال وللرجال كالجيوش."], ["أهؤلاء", "إشارة إلى ضعفاء المسلمين وهم في الجنة."], ["أو مما رزقكم الله", "أي من الطعام والشراب."]], "m": "نادى أصحاب الأعراف رجالاً من أهل النار يعرفونهم بسيماهم من سواد الوجوه وزرقة العيون: ما أغنى عنكم جمعكم للأموال والرجال، وما كنتم تستكبرون على الحق، وها أنتم في أشد العذاب؟ ثم يشيرون إلى ضعفة المسلمين الذين كانوا يسخرون منهم ويضربونهم ويهينونهم في الدنيا: أهؤلاء الذين أقسمتم لا ينالهم الله برحمة؟ ثم يقال لأصحاب الأعراف: ادخلوا الجنة لا خوف عليكم ولا أنتم تحزنون. ونادى أصحاب النار أصحاب الجنة لشدة عطشهم وجوعهم: أن أفيضوا علينا من الماء أو مما رزقكم الله من الطعام، قالوا: إن الله حرّمهما على الكافرين فلا ينالونهما بحال. ثم وصف الكافرين ليعرض جرائمهم عظة لقريش ولسائر الناس: الذين اتخذوا دينهم لهواً ولعباً وغرّتهم الحياة الدنيا، فاليوم ننساهم فنتركهم في عذابهم كما نسوا لقاء يومهم هذا فلم يعملوا له، وبما كانوا بآياتنا يجحدون.", "h": ["عدم إغناء المال والرجال أيّ إغناء لمن مات كافراً مشركاً من أهل الظلم والفساد.", "بشرى الضعفة من المسلمين بدخول الجنة وسعادتهم فيها.", "تحريم اتخاذ شيء من الدين لهواً ولعباً.", "التحذير من الاغترار بالدنيا حتى ينسى العبد آخرته، فلم يُعدّ لها ما ينفعه فيها من الإيمان وصالح الأعمال."], "k": "«فاليوم ننساهم كما نسوا لقاء يومهم هذا»… كم مرة نسيت ذلك اليوم في زحمة يومي؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (103, 7, 52, 58, 'سورة الأعراف ٥٢ – ٥٨', '«ألا له الخلق والأمر»، «ادعوا ربكم تضرعاً وخفية»، و«والبلد الطيب يخرج نباته بإذن ربه»', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 103) = $j$[{"lbl": "الآيات ٥٢ – ٥٤", "q": "وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٥٢﴾ هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٥٣﴾ إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٥٤﴾", "w": [["ولقد جئناهم", "أهل مكة أولاً، ثم سائر الناس."], ["بكتاب", "القرآن العظيم."], ["فصّلناه على علم", "بيّناه على علم منا، فبيّنا حلاله وحرامه، ووعده ووعيده، وقصصه ومواعظه."], ["تأويله", "تأويل ما جاء في الكتاب من وعد ووعيد، أي عاقبة ما أُنذروا به."], ["وضلّ عنهم", "ذهب ولم يعثروا عليه."], ["في ستة أيام", "هي الأحد إلى الجمعة."], ["يغشي الليل النهار", "يغطّي كل واحد منهما الآخر عند مجيئه."], ["حثيثاً", "سريعاً بلا انقطاع."], ["مسخّرات", "مذلّلات."], ["ألا", "أداة استفتاح وتنبيه."], ["له الخلق والأمر", "له المخلوقات والتصرّف فيها وحده لا شريك له."], ["تبارك", "عظمت قدرته، وجلّت عن الحصر خيراته وبركاته."], ["العالمين", "كل ما سوى الله فهو عالَم، أي علامة على خالقه وإلهه الحق."]], "m": "بعد عرض أحوال الناس يوم القيامة، أخبر الله أنه جاء قريشاً لهدايتهم بكتاب فصّله على علم: بيّن التوحيد ودلائله، والشرك وعوامله، والطاعة وآثارها الحسنة، والمعصية وآثارها السيئة، هدى ورحمة لقوم يؤمنون. ثم استبطأ إيمانهم: هل ينتظرون إلا تأويله، عاقبة ما أخبر به من القيامة وأهوالها والنار وعذابها؟ يوم يأتي تأويله يقول الذين نسوه من قبل فلم يعملوا بما ينجيهم: قد جاءت رسل ربنا بالحق، فيعترفون بما كانوا يجحدون، ويتمنّون ما لا يتحقّق: فهل لنا من شفعاء فيشفعوا لنا، أو نُردّ إلى الدنيا فنعمل غير الذي كنا نعمل؟ قد خسروا أنفسهم في جهنم، وغاب عنهم ما كانوا يفترون من شفاعة آلهتهم. إن ربكم الذي يحب أن تعبدوه وتدعوه الله الذي خلق السماوات والأرض في ستة أيام ثم استوى على العرش، يغشي الليل النهار يطلبه حثيثاً، والشمس والقمر والنجوم مسخّرات بأمره، هذا ربكم الحق لا إله غيره، أما الأصنام فمخلوقة عاجزة عن نفع نفسها، ألا له الخلق كله ملكاً وتصرّفاً، وله الأمر وحده في الملكوت كله، تبارك الله رب العالمين.", "h": ["لا ينفع الإيمان عند معاينة الموت والعذاب، كما لا ينفع يوم القيامة.", "يحسن التثبّت في الأمر والتأني عند العمل وترك العجلة، فالله قادر على خلق السماوات والأرض في ساعة، ولكن خلقها في ستة أيام بمقدار أيام الدنيا، تعليماً وإرشاداً إلى التثبّت في الأمور والتأني فيها.", "صفة من صفات الرب تعالى التي يجب الإيمان بها ويحرم تأويلها أو تكييفها، وهي استواؤه تعالى على عرشه.", "انحصار الخلق كل الخلق فيه تعالى فلا خالق إلا هو، والأمر كذلك فلا آمر ولا ناهي غيره، وهنا قال عمر: من بقي له شيء فليطلبه، إذ لم يبق شيء ما دام الخلق والأمر كلاهما لله."], "k": "«ألا له الخلق والأمر»… إذا كان الأمر كله له، فلماذا أطلب حاجتي من غيره؟"}, {"lbl": "الآيتان ٥٥ – ٥٦", "q": "ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿٥٥﴾ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ﴿٥٦﴾", "w": [["ادعوا ربكم", "سلوه حوائجكم الدنيوية والأخروية، فإنه ربكم فلا تستحيوا من سؤاله."], ["تضرّعاً وخفية", "حال كونكم ضارعين متذلّلين، مُخفي الدعاء غير رافعين أصواتكم به."], ["المعتدين", "في الدعاء وغيره، والاعتداء في الدعاء: أن يسأل الله ما لم تجرِ سنّته بإعطائه أو إيجاده أو تغييره، كأن يسأل أن يكون نبياً، أو أن يُردّ طفلاً أو صغيراً، أو يرفع صوته بالدعاء."], ["ولا تفسدوا في الأرض", "بالشرك والمعاصي بعد إصلاحها بالتوحيد والطاعات."], ["المحسنين", "الذين يحسنون أعمالهم ونياتهم بمراقبتهم الله تعالى في كل أحوالهم."]], "m": "لما عرّف الله عباده بنفسه، وأنه ربهم الحق الخالق الآمر، أمرهم أن يدعوه، وبيّن الحال التي يدعونه عليها ليستجيب لهم: ادعوا ربكم تضرّعاً، تذلّلاً وخشوعاً، وخفية، سراً لا جهراً، إنه لا يحب المعتدين، والاعتداء في الدعاء: أن يُدعى غير الله أو يُدعى معه غيره، ومنه طلب ذوات الأسباب بدون إعداد أسبابها، أو سؤال ما لم تجرِ سنّة الله به، كسؤال المرء أن يكون نبياً أو يُردّ من كهولته إلى شبابه. ثم نهاهم عن الفساد في الأرض بعد إصلاحها، ويكون بالشرك والمعاصي، كقتل الناس وغصب أموالهم وإفساد زروعهم، وإفساد عقولهم بالسحر والمخدّرات، وأعراضهم بالزنى. ثم حضّهم مرة أخرى على دعائه، فإن «الدعاء هو العبادة»: وادعوه خوفاً من عقابه وطمعاً في رحمته، إن رحمة الله قريب من المحسنين الذين يحسنون نياتهم وأعمالهم، ومن ذلك الدعاء، فمن أحسن الدعاء ظفر بالإجابة.", "h": ["وجوب دعاء الله تعالى، فإن الدعاء هو العبادة.", "بيان آداب الدعاء: أن يكون الداعي ضارعاً متذلّلاً، وأن يُخفي دعاءه فلا يجهر به، وأن يكون حال الدعاء خائفاً طامعاً، وأن لا يعتدي في الدعاء بدعاء غير الله تعالى أو سؤال ما لم تجرِ سنّة الله بإعطائه.", "حرمة الإفساد في الأرض بالشرك والمعاصي بعد أن أصلحها الله تعالى بالإسلام.", "الترغيب في الإحسان مطلقاً، خاصاً وعاماً، حيث إن الله تعالى يحب أهله."], "k": "«تضرّعاً وخفية… خوفاً وطمعاً»… هل يجمع دعائي اليوم التذلّل والخوف والرجاء؟"}, {"lbl": "الآيتان ٥٧ – ٥٨", "q": "وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا ثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٥٧﴾ وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ ﴿٥٨﴾", "w": [["الرياح", "جمع ريح، وهو الهواء المتحرك."], ["بُشراً", "جمع بشير، أي مبشّرات بقرب نزول المطر، وقُرئ نُشراً، أي تنشر السحاب للأمطار."], ["رحمته", "رحمة الله تعالى، وهي المطر."], ["أقلّت سحاباً ثقالاً", "حملت سحاباً ثقالاً مشبعاً ببخار الماء."], ["ميت", "لا نبات به ولا عشب ولا كلأ."], ["كذلك نُخرج الموتى", "كذلك نحيي الموتى ونخرجهم من قبورهم أحياء."], ["تذكّرون", "تتذكّرون فتؤمنون بالبعث والجزاء."], ["الطيب", "الطيب التربة."], ["خبُث", "خبثت تربته بأن كانت سبخة."], ["إلا نكداً", "إلا عسراً."], ["نصرّف الآيات", "ننوّعها ونخالف بين أساليبها، ونذكر في بعضها ما لم نذكره في بعضها، للهداية والتعليم."], ["لقوم يشكرون", "لأنهم هم الذين ينتفعون بالنعم بشكرها، بصرفها في محابّ الله."]], "m": "ما زال السياق في بيان مظاهر القدرة والرحمة الموجبة لعبادته وحده: وهو الذي يرسل الرياح مبشّرات بين يدي رحمته، المطر، حتى إذا حملت سحاباً ثقالاً ببخار الماء سقناه بقدرتنا لبلد ميت لا نبات به، فأنزلنا به الماء العذب، فأخرجنا به من كل الثمرات المختلفة الألوان والروائح والطعوم، كذلك نخرج الموتى من قبورهم، نريكموه بأبصاركم لعلكم تذكّرون أن القادر على إحياء موات الأرض قادر على إحياء موات الأجسام، فتؤمنوا بلقاء ربكم. ثم ضرب مثلاً للمؤمن والكافر: والبلد الطيب التربة يخرج نباته بإذن ربه بعد نزول المطر، وهذا مثل المؤمن ذي القلب الحي الطيب، إذا سمع الآيات زاد إيمانه وكثرت أعماله الصالحة، والذي خبُث، تربته سبخة أو حمأة، لا يخرج نباته إلا نكداً عسراً قليلاً غير صالح، وهذا مثل الكافر يسمع الآيات فلا يقبل عليها ولا ينتفع بها، فلا يعمل خيراً ولا يترك شراً. كذلك نصرّف الآيات لقوم يشكرون، إذ هم المنتفعون بها.", "h": ["تقرير عقيدة البعث والحياة بعد الموت للحساب والجزاء، إذ هي من أهم أركان الإيمان.", "الاستدلال بالحاضر على الغائب، وهو من العلوم النافعة.", "حسن ضرب الأمثال لتقريب المعاني إلى الأذهان.", "فضيلة الشكر، وهو صرف النعمة فيما من أجله وهبها الله تعالى للعبد."], "k": "«والبلد الطيب يخرج نباته بإذن ربه»… حين تنزل عليّ آيات الله، هل يُنبت قلبي عملاً، أم يبقى كالأرض السبخة؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 103;
insert into public.tdb_cards(topic, i, body) select 103, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٢ – ٥٤", "q": "وَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ هُدٗى وَرَحۡمَةٗ لِّقَوۡمٖ يُؤۡمِنُونَ ﴿٥٢﴾ هَلۡ يَنظُرُونَ إِلَّا تَأۡوِيلَهُۥۚ يَوۡمَ يَأۡتِي تَأۡوِيلُهُۥ يَقُولُ ٱلَّذِينَ نَسُوهُ مِن قَبۡلُ قَدۡ جَآءَتۡ رُسُلُ رَبِّنَا بِٱلۡحَقِّ فَهَل لَّنَا مِن شُفَعَآءَ فَيَشۡفَعُواْ لَنَآ أَوۡ نُرَدُّ فَنَعۡمَلَ غَيۡرَ ٱلَّذِي كُنَّا نَعۡمَلُۚ قَدۡ خَسِرُوٓاْ أَنفُسَهُمۡ وَضَلَّ عَنۡهُم مَّا كَانُواْ يَفۡتَرُونَ ﴿٥٣﴾ إِنَّ رَبَّكُمُ ٱللَّهُ ٱلَّذِي خَلَقَ ٱلسَّمَٰوَٰتِ وَٱلۡأَرۡضَ فِي سِتَّةِ أَيَّامٖ ثُمَّ ٱسۡتَوَىٰ عَلَى ٱلۡعَرۡشِۖ يُغۡشِي ٱلَّيۡلَ ٱلنَّهَارَ يَطۡلُبُهُۥ حَثِيثٗا وَٱلشَّمۡسَ وَٱلۡقَمَرَ وَٱلنُّجُومَ مُسَخَّرَٰتِۭ بِأَمۡرِهِۦٓۗ أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ تَبَارَكَ ٱللَّهُ رَبُّ ٱلۡعَٰلَمِينَ ﴿٥٤﴾", "w": [["ولقد جئناهم", "أهل مكة أولاً، ثم سائر الناس."], ["بكتاب", "القرآن العظيم."], ["فصّلناه على علم", "بيّناه على علم منا، فبيّنا حلاله وحرامه، ووعده ووعيده، وقصصه ومواعظه."], ["تأويله", "تأويل ما جاء في الكتاب من وعد ووعيد، أي عاقبة ما أُنذروا به."], ["وضلّ عنهم", "ذهب ولم يعثروا عليه."], ["في ستة أيام", "هي الأحد إلى الجمعة."], ["يغشي الليل النهار", "يغطّي كل واحد منهما الآخر عند مجيئه."], ["حثيثاً", "سريعاً بلا انقطاع."], ["مسخّرات", "مذلّلات."], ["ألا", "أداة استفتاح وتنبيه."], ["له الخلق والأمر", "له المخلوقات والتصرّف فيها وحده لا شريك له."], ["تبارك", "عظمت قدرته، وجلّت عن الحصر خيراته وبركاته."], ["العالمين", "كل ما سوى الله فهو عالَم، أي علامة على خالقه وإلهه الحق."]], "m": "بعد عرض أحوال الناس يوم القيامة، أخبر الله أنه جاء قريشاً لهدايتهم بكتاب فصّله على علم: بيّن التوحيد ودلائله، والشرك وعوامله، والطاعة وآثارها الحسنة، والمعصية وآثارها السيئة، هدى ورحمة لقوم يؤمنون. ثم استبطأ إيمانهم: هل ينتظرون إلا تأويله، عاقبة ما أخبر به من القيامة وأهوالها والنار وعذابها؟ يوم يأتي تأويله يقول الذين نسوه من قبل فلم يعملوا بما ينجيهم: قد جاءت رسل ربنا بالحق، فيعترفون بما كانوا يجحدون، ويتمنّون ما لا يتحقّق: فهل لنا من شفعاء فيشفعوا لنا، أو نُردّ إلى الدنيا فنعمل غير الذي كنا نعمل؟ قد خسروا أنفسهم في جهنم، وغاب عنهم ما كانوا يفترون من شفاعة آلهتهم. إن ربكم الذي يحب أن تعبدوه وتدعوه الله الذي خلق السماوات والأرض في ستة أيام ثم استوى على العرش، يغشي الليل النهار يطلبه حثيثاً، والشمس والقمر والنجوم مسخّرات بأمره، هذا ربكم الحق لا إله غيره، أما الأصنام فمخلوقة عاجزة عن نفع نفسها، ألا له الخلق كله ملكاً وتصرّفاً، وله الأمر وحده في الملكوت كله، تبارك الله رب العالمين.", "h": ["لا ينفع الإيمان عند معاينة الموت والعذاب، كما لا ينفع يوم القيامة.", "يحسن التثبّت في الأمر والتأني عند العمل وترك العجلة، فالله قادر على خلق السماوات والأرض في ساعة، ولكن خلقها في ستة أيام بمقدار أيام الدنيا، تعليماً وإرشاداً إلى التثبّت في الأمور والتأني فيها.", "صفة من صفات الرب تعالى التي يجب الإيمان بها ويحرم تأويلها أو تكييفها، وهي استواؤه تعالى على عرشه.", "انحصار الخلق كل الخلق فيه تعالى فلا خالق إلا هو، والأمر كذلك فلا آمر ولا ناهي غيره، وهنا قال عمر: من بقي له شيء فليطلبه، إذ لم يبق شيء ما دام الخلق والأمر كلاهما لله."], "k": "«ألا له الخلق والأمر»… إذا كان الأمر كله له، فلماذا أطلب حاجتي من غيره؟"}, {"lbl": "الآيتان ٥٥ – ٥٦", "q": "ٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ﴿٥٥﴾ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا وَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ﴿٥٦﴾", "w": [["ادعوا ربكم", "سلوه حوائجكم الدنيوية والأخروية، فإنه ربكم فلا تستحيوا من سؤاله."], ["تضرّعاً وخفية", "حال كونكم ضارعين متذلّلين، مُخفي الدعاء غير رافعين أصواتكم به."], ["المعتدين", "في الدعاء وغيره، والاعتداء في الدعاء: أن يسأل الله ما لم تجرِ سنّته بإعطائه أو إيجاده أو تغييره، كأن يسأل أن يكون نبياً، أو أن يُردّ طفلاً أو صغيراً، أو يرفع صوته بالدعاء."], ["ولا تفسدوا في الأرض", "بالشرك والمعاصي بعد إصلاحها بالتوحيد والطاعات."], ["المحسنين", "الذين يحسنون أعمالهم ونياتهم بمراقبتهم الله تعالى في كل أحوالهم."]], "m": "لما عرّف الله عباده بنفسه، وأنه ربهم الحق الخالق الآمر، أمرهم أن يدعوه، وبيّن الحال التي يدعونه عليها ليستجيب لهم: ادعوا ربكم تضرّعاً، تذلّلاً وخشوعاً، وخفية، سراً لا جهراً، إنه لا يحب المعتدين، والاعتداء في الدعاء: أن يُدعى غير الله أو يُدعى معه غيره، ومنه طلب ذوات الأسباب بدون إعداد أسبابها، أو سؤال ما لم تجرِ سنّة الله به، كسؤال المرء أن يكون نبياً أو يُردّ من كهولته إلى شبابه. ثم نهاهم عن الفساد في الأرض بعد إصلاحها، ويكون بالشرك والمعاصي، كقتل الناس وغصب أموالهم وإفساد زروعهم، وإفساد عقولهم بالسحر والمخدّرات، وأعراضهم بالزنى. ثم حضّهم مرة أخرى على دعائه، فإن «الدعاء هو العبادة»: وادعوه خوفاً من عقابه وطمعاً في رحمته، إن رحمة الله قريب من المحسنين الذين يحسنون نياتهم وأعمالهم، ومن ذلك الدعاء، فمن أحسن الدعاء ظفر بالإجابة.", "h": ["وجوب دعاء الله تعالى، فإن الدعاء هو العبادة.", "بيان آداب الدعاء: أن يكون الداعي ضارعاً متذلّلاً، وأن يُخفي دعاءه فلا يجهر به، وأن يكون حال الدعاء خائفاً طامعاً، وأن لا يعتدي في الدعاء بدعاء غير الله تعالى أو سؤال ما لم تجرِ سنّة الله بإعطائه.", "حرمة الإفساد في الأرض بالشرك والمعاصي بعد أن أصلحها الله تعالى بالإسلام.", "الترغيب في الإحسان مطلقاً، خاصاً وعاماً، حيث إن الله تعالى يحب أهله."], "k": "«تضرّعاً وخفية… خوفاً وطمعاً»… هل يجمع دعائي اليوم التذلّل والخوف والرجاء؟"}, {"lbl": "الآيتان ٥٧ – ٥٨", "q": "وَهُوَ ٱلَّذِي يُرۡسِلُ ٱلرِّيَٰحَ بُشۡرَۢا بَيۡنَ يَدَيۡ رَحۡمَتِهِۦۖ حَتَّىٰٓ إِذَآ أَقَلَّتۡ سَحَابٗا ثِقَالٗا سُقۡنَٰهُ لِبَلَدٖ مَّيِّتٖ فَأَنزَلۡنَا بِهِ ٱلۡمَآءَ فَأَخۡرَجۡنَا بِهِۦ مِن كُلِّ ٱلثَّمَرَٰتِۚ كَذَٰلِكَ نُخۡرِجُ ٱلۡمَوۡتَىٰ لَعَلَّكُمۡ تَذَكَّرُونَ ﴿٥٧﴾ وَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ ﴿٥٨﴾", "w": [["الرياح", "جمع ريح، وهو الهواء المتحرك."], ["بُشراً", "جمع بشير، أي مبشّرات بقرب نزول المطر، وقُرئ نُشراً، أي تنشر السحاب للأمطار."], ["رحمته", "رحمة الله تعالى، وهي المطر."], ["أقلّت سحاباً ثقالاً", "حملت سحاباً ثقالاً مشبعاً ببخار الماء."], ["ميت", "لا نبات به ولا عشب ولا كلأ."], ["كذلك نُخرج الموتى", "كذلك نحيي الموتى ونخرجهم من قبورهم أحياء."], ["تذكّرون", "تتذكّرون فتؤمنون بالبعث والجزاء."], ["الطيب", "الطيب التربة."], ["خبُث", "خبثت تربته بأن كانت سبخة."], ["إلا نكداً", "إلا عسراً."], ["نصرّف الآيات", "ننوّعها ونخالف بين أساليبها، ونذكر في بعضها ما لم نذكره في بعضها، للهداية والتعليم."], ["لقوم يشكرون", "لأنهم هم الذين ينتفعون بالنعم بشكرها، بصرفها في محابّ الله."]], "m": "ما زال السياق في بيان مظاهر القدرة والرحمة الموجبة لعبادته وحده: وهو الذي يرسل الرياح مبشّرات بين يدي رحمته، المطر، حتى إذا حملت سحاباً ثقالاً ببخار الماء سقناه بقدرتنا لبلد ميت لا نبات به، فأنزلنا به الماء العذب، فأخرجنا به من كل الثمرات المختلفة الألوان والروائح والطعوم، كذلك نخرج الموتى من قبورهم، نريكموه بأبصاركم لعلكم تذكّرون أن القادر على إحياء موات الأرض قادر على إحياء موات الأجسام، فتؤمنوا بلقاء ربكم. ثم ضرب مثلاً للمؤمن والكافر: والبلد الطيب التربة يخرج نباته بإذن ربه بعد نزول المطر، وهذا مثل المؤمن ذي القلب الحي الطيب، إذا سمع الآيات زاد إيمانه وكثرت أعماله الصالحة، والذي خبُث، تربته سبخة أو حمأة، لا يخرج نباته إلا نكداً عسراً قليلاً غير صالح، وهذا مثل الكافر يسمع الآيات فلا يقبل عليها ولا ينتفع بها، فلا يعمل خيراً ولا يترك شراً. كذلك نصرّف الآيات لقوم يشكرون، إذ هم المنتفعون بها.", "h": ["تقرير عقيدة البعث والحياة بعد الموت للحساب والجزاء، إذ هي من أهم أركان الإيمان.", "الاستدلال بالحاضر على الغائب، وهو من العلوم النافعة.", "حسن ضرب الأمثال لتقريب المعاني إلى الأذهان.", "فضيلة الشكر، وهو صرف النعمة فيما من أجله وهبها الله تعالى للعبد."], "k": "«والبلد الطيب يخرج نباته بإذن ربه»… حين تنزل عليّ آيات الله، هل يُنبت قلبي عملاً، أم يبقى كالأرض السبخة؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (104, 7, 59, 72, 'سورة الأعراف ٥٩ – ٧٢', 'نوح ﵇ مع قومه، وهود ﵇ مع عاد', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 104) = $j$[{"lbl": "الآيات ٥٩ – ٦٤", "q": "لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿٥٩﴾ قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٦٠﴾ قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٦١﴾ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٦٢﴾ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ ﴿٦٣﴾ فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ ﴿٦٤﴾", "w": [["نوحاً", "أول الرسل، العبد الشكور، نوح بن لمك بن متوشلخ بن أخنوخ، أحد أولي العزم الخمسة من الرسل، عاش داعياً وهادياً ومعلّماً ألفاً ومائتين وأربعين سنة، مدة الدعوة منها ألف سنة إلا خمسين عاماً."], ["الملأ", "أشراف القوم ورؤساؤهم الذين يملؤون العين والمجلس."], ["أوَعجبتم", "الاستفهام للإنكار، والواو عاطفة، والمعطوف عليه جملة محذوفة هي: أكذّبتم وعجبتم؟"], ["لينذركم", "أي العذاب المترتّب على الكفر والمعاصي."], ["ولتتقوا", "أي الله تعالى، بالإيمان به وتوحيده وطاعته، فتُرحمون فلا تُعذّبون."], ["والذين معه في الفلك", "المؤمنون من قومه، والفلك: السفينة التي صنعها بأمر الله."], ["عمين", "جمع عَمٍ، وهو أعمى البصيرة، أما أعمى العينين فيقال فيه أعمى."]], "m": "هذا شروع في قصص ستة من الرسل: نوح وهود وصالح ولوط وشعيب وموسى ﵈، تنويعاً لأسلوب الدعوة، ليشاهد كفار قريش صوراً ناطقة لأمم سبقت، كيف بدأت وبم خُتمت، لعلهم يتّعظون، وفيه تقرير نبوة محمد ﷺ، إذ لولا الوحي ما تأتّى له قصّ أخبار الماضين، وفيه للمؤمنين عبر تحملهم على الثبات والصبر. لقد أرسلنا نوحاً إلى قومه فقال: يا قوم اعبدوا الله ما لكم من إله غيره، إذ الإله الحق من يخلق ويرزق ويدبّر، ويحيي ويميت، فأين هذا من آلهة نحتّموها بأيديكم عمياء صمّاء بكماء؟ إني أخاف عليكم عذاب يوم عظيم. قال الملأ من قومه، أهل الحل والعقد: إنا لنراك في ضلال مبين بموقفك العدائي من آلهتنا. قال: يا قوم ليس بي ضلالة، فكيف بالضلال كله؟ ولكني رسول من رب العالمين، أبلّغكم رسالات ربي وأنصح لكم، وأعلم من الله ما لا تعلمون من عظمته وجلاله ورحمته ونكاله، أوَعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون؟ أمن هذا يتعجّب العقلاء؟ وقد دام حديثه معهم ألف سنة إلا خمسين عاماً، فكذّبوه فأنجيناه والذين معه في الفلك، وأغرقنا الذين كذّبوا بآياتنا، إنهم كانوا قوماً عمين لا يبصرون الآيات ولا يرون النذر.", "h": ["تقرير نبوة محمد ﷺ كنبوة نوح ﵇.", "تقرير وتأكيد التوحيد، وبيان معنى لا إله إلا الله.", "التحذير من عذاب يوم القيامة بالتذكير به.", "أصحاب المنافع من مراكز وغيرها هم الذين يردّون دعوة الحق لمنافاتها للباطل.", "تقرير مبدأ العاقبة للمتقين.", "عمى القلوب أخطر من عمى العيون على صاحبه."], "k": "«ألف سنة إلا خمسين عاماً»… نوح ﵇ لم يملّ الدعوة؛ فكم مرة نصحت ثم مللت؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "۞وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٦٥﴾ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ ﴿٦٦﴾ قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٦٧﴾ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ ﴿٦٨﴾ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٦٩﴾", "w": [["وإلى عاد", "ولقد أرسلنا إلى عاد، وهم قبيلة عاد، وعاد أبو القبيلة، وهو عاد بن عوص بن إرم بن سام بن نوح ﵇."], ["أخاهم هوداً", "أخاهم في النسب لا في الدين، وهود هو هود بن شالخ بن أرفخشد بن سام بن نوح ﵇."], ["أفلا تتقون", "أتصرّون على الشرك فلا تتقون عذاب الله بالإيمان به وتوحيده؟ والاستفهام إنكاري."], ["في سفاهة", "السفاهة كالسفه، وهو خفة العقل وقلة الإدراك والحلم."], ["أمين", "لا أخونكم ولا أغشّكم ولا أكذبكم، كما أني مأمون على رسالتي."], ["بسطة", "طولاً في الأجسام، إذ كانوا عمالقة من عظم أجسادهم وطولها."], ["آلاء الله", "نعمه، واحدها: إلْي وأَلْي وإلْو."], ["تفلحون", "بالنجاة من النار في الآخرة، والهلاك في الدنيا."]], "m": "هذا القصص الثاني: هود ﵇ مع قومه عاد الأولى، التي أهلكها الله بريح صرصر عاتية سخّرها عليهم سبع ليال وثمانية أيام. وأرسلنا إلى عاد أخاهم في النسب هوداً، قال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، إذ هو يخلق ويرزق ويدبّر، وآلهتكم لا تملك نفعاً ولا ضراً، أفلا تتقون؟ قال الملأ الذين كفروا من قومه بأسوأ إجابة لكبريائهم: إنا لنراك في سفاهة، حمق وطيش، وإلا كيف تخرج عن إجماع قومك؟ وإنا لنظنّك من الكاذبين. قال: يا قوم ليس بي سفاهة، ولكني رسول من رب العالمين، أبلّغكم رسالات ربي، وأنا لكم ناصح أمين، لا أغشّكم ولا أخونكم، أوَعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم عواقب كفركم؟ ثم ذكّرهم بنعم الله لعلهم يتراجعون: واذكروا إذ جعلكم خلفاء من بعد قوم نوح بعد أن أهلكهم بالطوفان، وزادكم في الخلق بسطة، أجساماً قوية وقامات طويلة، فاذكروا آلاء الله لعلكم تفلحون، فإن ذكرتموها بقلوبكم شكرتموها بأقوالكم وأعمالكم، فتنجون من المرهوب وتظفرون بالمحبوب.", "h": ["الدعوة إلى عبادة الله وترك عبادة ما سواه، وهو معنى لا إله إلا الله.", "مشروعية دفع الاتهام، وتبرئة الإنسان نفسه مما يُتّهم به من الباطل.", "من وظائف الرسل ﵈ البلاغ لما أُمروا بإبلاغه.", "فضيلة النصح وخلق الأمانة.", "استحسان التذكير بالنعم، فإن ذلك موجب للشكر والطاعة."], "k": "«وأنا لكم ناصح أمين»… هل يجد الناس فيّ النصح والأمانة، حتى حين يردّون نصحي؟"}, {"lbl": "الآيات ٧٠ – ٧٢", "q": "قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٧٠﴾ قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿٧١﴾ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ ﴿٧٢﴾", "w": [["ونذر", "أي نترك."], ["بما تعدنا", "أي من العذاب."], ["رجس", "سخط موجب للعذاب."], ["أتجادلونني", "أتخاصمونني؟"], ["في أسماء", "في الأصنام التي أطلقوا عليها أسماء، كاللات والعزى ومناة عند قريش ومشركي العرب."], ["من سلطان", "من حجة ولا برهان يثبت أنها تستحق العبادة."], ["دابر", "دابر القوم: آخرهم، لأنه إذا هلك آخر القوم هلك أولهم بلا ريب."]], "m": "ما زال السياق في قصص هود ﵇: ردّ الملأ على دعوته: أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا؟ وهدّدوه: فأتنا بما تعدنا من العذاب إن كنت من الصادقين. فرد عليهم: قد وقع عليكم من ربكم رجس وغضب، فأصبح عذابكم متوقّعاً كل يوم، أتجادلونني في أسماء سمّيتموها أنتم وآباؤكم ما نزّل الله بها من سلطان؟ فانتظروا ما سيحل بكم إني معكم من المنتظرين. فأنجيناه والذين معه من المؤمنين برحمة منا خاصة، وقطعنا دابر الذين كذّبوا بآياتنا وما كانوا مؤمنين، أهلكناهم بريح خارقة تدمّر كل شيء بأمر ربها، فأصبحوا لا يُرى إلا مساكنهم، وكذلك جزاء الظالمين.", "h": ["احتجاج المشركين على صحة باطلهم بفعل آبائهم وأجدادهم يكاد يكون سنة مطّردة في الأمم والشعوب، وهو التقليد المذموم.", "من حمق الكافرين استعجالهم بالعذاب ومطالبتهم به.", "آلهة الوثنيين مجرّد أسماء لا حقائق لها، إذ إطلاق المرء اسم إله على حجر لا يجعله إلهاً ينفع ويضر، ويحيي ويميت.", "قدرة الله تعالى ولطفه تتجلّى في إهلاك عاد وإنجاء هود والمؤمنين."], "k": "«أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا»… هل أُبقي على عادة لأنها عادة الآباء، وأنا أعلم أنها تخالف الحق؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 104;
insert into public.tdb_cards(topic, i, body) select 104, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٥٩ – ٦٤", "q": "لَقَدۡ أَرۡسَلۡنَا نُوحًا إِلَىٰ قَوۡمِهِۦ فَقَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓ إِنِّيٓ أَخَافُ عَلَيۡكُمۡ عَذَابَ يَوۡمٍ عَظِيمٖ ﴿٥٩﴾ قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ ﴿٦٠﴾ قَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٦١﴾ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ﴿٦٢﴾ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡ وَلِتَتَّقُواْ وَلَعَلَّكُمۡ تُرۡحَمُونَ ﴿٦٣﴾ فَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ ﴿٦٤﴾", "w": [["نوحاً", "أول الرسل، العبد الشكور، نوح بن لمك بن متوشلخ بن أخنوخ، أحد أولي العزم الخمسة من الرسل، عاش داعياً وهادياً ومعلّماً ألفاً ومائتين وأربعين سنة، مدة الدعوة منها ألف سنة إلا خمسين عاماً."], ["الملأ", "أشراف القوم ورؤساؤهم الذين يملؤون العين والمجلس."], ["أوَعجبتم", "الاستفهام للإنكار، والواو عاطفة، والمعطوف عليه جملة محذوفة هي: أكذّبتم وعجبتم؟"], ["لينذركم", "أي العذاب المترتّب على الكفر والمعاصي."], ["ولتتقوا", "أي الله تعالى، بالإيمان به وتوحيده وطاعته، فتُرحمون فلا تُعذّبون."], ["والذين معه في الفلك", "المؤمنون من قومه، والفلك: السفينة التي صنعها بأمر الله."], ["عمين", "جمع عَمٍ، وهو أعمى البصيرة، أما أعمى العينين فيقال فيه أعمى."]], "m": "هذا شروع في قصص ستة من الرسل: نوح وهود وصالح ولوط وشعيب وموسى ﵈، تنويعاً لأسلوب الدعوة، ليشاهد كفار قريش صوراً ناطقة لأمم سبقت، كيف بدأت وبم خُتمت، لعلهم يتّعظون، وفيه تقرير نبوة محمد ﷺ، إذ لولا الوحي ما تأتّى له قصّ أخبار الماضين، وفيه للمؤمنين عبر تحملهم على الثبات والصبر. لقد أرسلنا نوحاً إلى قومه فقال: يا قوم اعبدوا الله ما لكم من إله غيره، إذ الإله الحق من يخلق ويرزق ويدبّر، ويحيي ويميت، فأين هذا من آلهة نحتّموها بأيديكم عمياء صمّاء بكماء؟ إني أخاف عليكم عذاب يوم عظيم. قال الملأ من قومه، أهل الحل والعقد: إنا لنراك في ضلال مبين بموقفك العدائي من آلهتنا. قال: يا قوم ليس بي ضلالة، فكيف بالضلال كله؟ ولكني رسول من رب العالمين، أبلّغكم رسالات ربي وأنصح لكم، وأعلم من الله ما لا تعلمون من عظمته وجلاله ورحمته ونكاله، أوَعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم ولتتقوا ولعلكم ترحمون؟ أمن هذا يتعجّب العقلاء؟ وقد دام حديثه معهم ألف سنة إلا خمسين عاماً، فكذّبوه فأنجيناه والذين معه في الفلك، وأغرقنا الذين كذّبوا بآياتنا، إنهم كانوا قوماً عمين لا يبصرون الآيات ولا يرون النذر.", "h": ["تقرير نبوة محمد ﷺ كنبوة نوح ﵇.", "تقرير وتأكيد التوحيد، وبيان معنى لا إله إلا الله.", "التحذير من عذاب يوم القيامة بالتذكير به.", "أصحاب المنافع من مراكز وغيرها هم الذين يردّون دعوة الحق لمنافاتها للباطل.", "تقرير مبدأ العاقبة للمتقين.", "عمى القلوب أخطر من عمى العيون على صاحبه."], "k": "«ألف سنة إلا خمسين عاماً»… نوح ﵇ لم يملّ الدعوة؛ فكم مرة نصحت ثم مللت؟"}, {"lbl": "الآيات ٦٥ – ٦٩", "q": "۞وَإِلَىٰ عَادٍ أَخَاهُمۡ هُودٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥٓۚ أَفَلَا تَتَّقُونَ ﴿٦٥﴾ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ كَفَرُواْ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي سَفَاهَةٖ وَإِنَّا لَنَظُنُّكَ مِنَ ٱلۡكَٰذِبِينَ ﴿٦٦﴾ قَالَ يَٰقَوۡمِ لَيۡسَ بِي سَفَاهَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ﴿٦٧﴾ أُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ ﴿٦٨﴾ أَوَعَجِبۡتُمۡ أَن جَآءَكُمۡ ذِكۡرٞ مِّن رَّبِّكُمۡ عَلَىٰ رَجُلٖ مِّنكُمۡ لِيُنذِرَكُمۡۚ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ﴿٦٩﴾", "w": [["وإلى عاد", "ولقد أرسلنا إلى عاد، وهم قبيلة عاد، وعاد أبو القبيلة، وهو عاد بن عوص بن إرم بن سام بن نوح ﵇."], ["أخاهم هوداً", "أخاهم في النسب لا في الدين، وهود هو هود بن شالخ بن أرفخشد بن سام بن نوح ﵇."], ["أفلا تتقون", "أتصرّون على الشرك فلا تتقون عذاب الله بالإيمان به وتوحيده؟ والاستفهام إنكاري."], ["في سفاهة", "السفاهة كالسفه، وهو خفة العقل وقلة الإدراك والحلم."], ["أمين", "لا أخونكم ولا أغشّكم ولا أكذبكم، كما أني مأمون على رسالتي."], ["بسطة", "طولاً في الأجسام، إذ كانوا عمالقة من عظم أجسادهم وطولها."], ["آلاء الله", "نعمه، واحدها: إلْي وأَلْي وإلْو."], ["تفلحون", "بالنجاة من النار في الآخرة، والهلاك في الدنيا."]], "m": "هذا القصص الثاني: هود ﵇ مع قومه عاد الأولى، التي أهلكها الله بريح صرصر عاتية سخّرها عليهم سبع ليال وثمانية أيام. وأرسلنا إلى عاد أخاهم في النسب هوداً، قال: يا قوم اعبدوا الله وحده، ما لكم من إله غيره، إذ هو يخلق ويرزق ويدبّر، وآلهتكم لا تملك نفعاً ولا ضراً، أفلا تتقون؟ قال الملأ الذين كفروا من قومه بأسوأ إجابة لكبريائهم: إنا لنراك في سفاهة، حمق وطيش، وإلا كيف تخرج عن إجماع قومك؟ وإنا لنظنّك من الكاذبين. قال: يا قوم ليس بي سفاهة، ولكني رسول من رب العالمين، أبلّغكم رسالات ربي، وأنا لكم ناصح أمين، لا أغشّكم ولا أخونكم، أوَعجبتم أن جاءكم ذكر من ربكم على رجل منكم لينذركم عواقب كفركم؟ ثم ذكّرهم بنعم الله لعلهم يتراجعون: واذكروا إذ جعلكم خلفاء من بعد قوم نوح بعد أن أهلكهم بالطوفان، وزادكم في الخلق بسطة، أجساماً قوية وقامات طويلة، فاذكروا آلاء الله لعلكم تفلحون، فإن ذكرتموها بقلوبكم شكرتموها بأقوالكم وأعمالكم، فتنجون من المرهوب وتظفرون بالمحبوب.", "h": ["الدعوة إلى عبادة الله وترك عبادة ما سواه، وهو معنى لا إله إلا الله.", "مشروعية دفع الاتهام، وتبرئة الإنسان نفسه مما يُتّهم به من الباطل.", "من وظائف الرسل ﵈ البلاغ لما أُمروا بإبلاغه.", "فضيلة النصح وخلق الأمانة.", "استحسان التذكير بالنعم، فإن ذلك موجب للشكر والطاعة."], "k": "«وأنا لكم ناصح أمين»… هل يجد الناس فيّ النصح والأمانة، حتى حين يردّون نصحي؟"}, {"lbl": "الآيات ٧٠ – ٧٢", "q": "قَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّـٰدِقِينَ ﴿٧٠﴾ قَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ فَٱنتَظِرُوٓاْ إِنِّي مَعَكُم مِّنَ ٱلۡمُنتَظِرِينَ ﴿٧١﴾ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ بِرَحۡمَةٖ مِّنَّا وَقَطَعۡنَا دَابِرَ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَاۖ وَمَا كَانُواْ مُؤۡمِنِينَ ﴿٧٢﴾", "w": [["ونذر", "أي نترك."], ["بما تعدنا", "أي من العذاب."], ["رجس", "سخط موجب للعذاب."], ["أتجادلونني", "أتخاصمونني؟"], ["في أسماء", "في الأصنام التي أطلقوا عليها أسماء، كاللات والعزى ومناة عند قريش ومشركي العرب."], ["من سلطان", "من حجة ولا برهان يثبت أنها تستحق العبادة."], ["دابر", "دابر القوم: آخرهم، لأنه إذا هلك آخر القوم هلك أولهم بلا ريب."]], "m": "ما زال السياق في قصص هود ﵇: ردّ الملأ على دعوته: أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا؟ وهدّدوه: فأتنا بما تعدنا من العذاب إن كنت من الصادقين. فرد عليهم: قد وقع عليكم من ربكم رجس وغضب، فأصبح عذابكم متوقّعاً كل يوم، أتجادلونني في أسماء سمّيتموها أنتم وآباؤكم ما نزّل الله بها من سلطان؟ فانتظروا ما سيحل بكم إني معكم من المنتظرين. فأنجيناه والذين معه من المؤمنين برحمة منا خاصة، وقطعنا دابر الذين كذّبوا بآياتنا وما كانوا مؤمنين، أهلكناهم بريح خارقة تدمّر كل شيء بأمر ربها، فأصبحوا لا يُرى إلا مساكنهم، وكذلك جزاء الظالمين.", "h": ["احتجاج المشركين على صحة باطلهم بفعل آبائهم وأجدادهم يكاد يكون سنة مطّردة في الأمم والشعوب، وهو التقليد المذموم.", "من حمق الكافرين استعجالهم بالعذاب ومطالبتهم به.", "آلهة الوثنيين مجرّد أسماء لا حقائق لها، إذ إطلاق المرء اسم إله على حجر لا يجعله إلهاً ينفع ويضر، ويحيي ويميت.", "قدرة الله تعالى ولطفه تتجلّى في إهلاك عاد وإنجاء هود والمؤمنين."], "k": "«أجئتنا لنعبد الله وحده ونذر ما كان يعبد آباؤنا»… هل أُبقي على عادة لأنها عادة الآباء، وأنا أعلم أنها تخالف الحق؟"}]$j$::jsonb) with ordinality x(e, i);
insert into public.tdb_topics(n, surah, a_from, a_to, label, title, pub) values (105, 7, 73, 87, 'سورة الأعراف ٧٣ – ٨٧', 'صالح ﵇ وناقة الله، ولوط ﵇ وقومه، وشعيب ﵇ وأهل مدين', false)
  on conflict (n) do update set surah = excluded.surah, a_from = excluded.a_from, a_to = excluded.a_to, label = excluded.label, title = excluded.title,
    rev = public.tdb_topics.rev + case when (select coalesce(jsonb_agg(c.body order by c.i), '[]'::jsonb) from public.tdb_cards c where c.topic = 105) = $j$[{"lbl": "الآيات ٧٣ – ٧٦", "q": "وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ﴿٧٣﴾ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٧٤﴾ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ ﴿٧٥﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ ﴿٧٦﴾", "w": [["وإلى ثمود", "أرسلنا إلى ثمود، وثمود قبيلة سُمّيت باسم جدها، وهو ثمود بن عابر بن إرم بن سام بن نوح."], ["أخاهم صالحاً", "أي في النسب، وصالح هو صالح بن عبيد بن آسف بن ماشح بن عبيد بن حاذر بن ثمود."], ["آية", "علامة على صدقي في أني رسول الله إليكم."], ["وبوّأكم في الأرض", "أنزلكم فيها منازل تحبون فيها."], ["وتنحتون", "تنجرون الحجارة في الجبال لتتخذوا منازل تسكنونها."], ["آلاء الله", "نعم الله تعالى، وهي كثيرة."], ["ولا تعثوا", "لا تفسدوا في الأرض مفسدين."], ["استكبروا", "عتوا وطغوا وتكبّروا فلم يقبلوا الحق ولم يعترفوا به."]], "m": "وأرسلنا إلى قبيلة ثمود أخاهم صالحاً بكلمة التوحيد: يا قوم اعبدوا الله ما لكم من إله غيره، وهذا مدلول «لا إله إلا الله»، قد جاءتكم بيّنة من ربكم تشهد بأني رسوله، وهي ناقة تخرج من صخرة في جبل: هذه ناقة الله لكم آية، فذروها تأكل في أرض الله ولا تمسّوها بسوء فيأخذكم عذاب أليم. فكانت ترعى في المرج وتأتي إلى ماء القوم فتشربه كله، فيتحوّل في بطنها لبناً خالصاً فيحلبون ما شاؤوا، وجعل لها شرباً ولهم شرب يوم معلوم. ووعظهم: واذكروا إذ جعلكم خلفاء من بعد عاد، وكانت ديار عاد بحضرموت جنوب الجزيرة، وديار ثمود بالحجر شمالها بين الحجاز والشام، وبوّأكم في الأرض تتخذون من سهولها قصوراً تسكنونها في الصيف، وتنحتون الجبال بيوتاً تسكنونها في الشتاء، فاذكروا آلاء الله لتشكروها بعبادته وحده، ولا تعثوا في الأرض مفسدين بالشرك والمعاصي. فقال الملأ الذين استكبروا للمؤمنين من ضعفة القوم سخرية: أتعلمون أن صالحاً مرسل من ربه؟ قالوا صريحة غير خائفين: إنا بما أُرسل به مؤمنون، قال المستكبرون: إنا بالذي آمنتم به كافرون، ولم يقولوا «بما أُرسل به» حتى لا يعترفوا بالرسالة ولو في جواب.", "h": ["اتحاد دعوة الرسل في الإيمان بالله والكفر بالطاغوت، أي في عبادة الله وحده.", "تقرير إرسال الرسل بالآيات، وهي المعجزات، وآية صالح أعجب آية، وهي الناقة.", "وجوب التذكير بنعم الله، إذ هو الباعث على الشكر، والشكر هو الطاعة.", "النهي عن الفساد في الأرض بالشرك وارتكاب المعاصي.", "الضعفة هم غالباً أتباع الأنبياء، وذلك لخلوّهم من الموانع، كالمحافظة على المنصب أو الجاه أو المال، وعدم انغماسهم في الملاذّ والشهوات."], "k": "«إنا بما أُرسل به مؤمنون»… الضعفاء قالوها بلا خوف؛ فهل أُعلن الحق حين يسخر منه الأقوياء؟"}, {"lbl": "الآيات ٧٧ – ٧٩", "q": "فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ ﴿٧٧﴾ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٧٨﴾ فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ ﴿٧٩﴾", "w": [["فعقروا الناقة", "نحروها بعد أن عقروا قوائمها، أي قطعوها، والناقة هي الآية."], ["وعتوا عن أمر ربهم", "تمرّدوا عن الأمر وعصوا فلم يطيعوا."], ["الرجفة", "المرة من رجف إذا اضطرب، وذلك لما سمعوا الصيحة أخذتهم الرجفة."], ["جاثمين", "باركين على الركب كما يجثم الطير، أي هلكى على ركبهم."], ["فتولّى عنهم", "بعد أن هلكوا نظر إليهم صالح وهم جاثمون، وقال راثياً لحالهم: «يا قوم لقد أبلغتكم رسالة ربي…» إلى قوله: «ولكن لا تحبون الناصحين»، ثم أعرض عنهم وانصرف."]], "m": "بعد تلك الدعوة الطويلة، والمستكبرون يردّونها بصلف، وقد أوتوا الناقة آية مبصرة، تمالؤوا أخيراً على قتلها: فعقروا الناقة، قطعوا أرجلها ثم نحروها، وعتوا عن أمر ربهم، إذ أمرهم أن يتركوها ولا يمسّوها بسوء، فعقروها تحدّياً وعناداً، وقالوا: يا صالح، بدل أن يقولوا: يا رسول الله، ائتنا بما تعدنا من العذاب إن كنت من المرسلين. فأخذتهم الرجفة، هزّة عنيفة اضطربت لها القلوب والنفوس، فأصبحوا في دارهم جاثمين هلكى على ركبهم. ولما هلكوا وقف عليهم صالح كالمودّع، كما وقف رسول الله ﷺ على أهل القليب ببدر فناداهم: يا فلان يا فلان، فقال كالراثي المتحسّر: يا قوم لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين، وتولّى عنهم وانصرف.", "h": ["حلول نقمة الله تعالى بكل من عتا عن أمره سبحانه وتعالى.", "مشروعية الرثاء لمن مات أو أُصيب بمصاب عظيم.", "علامة قرب ساعة الهلاك إذا أصبح الناس يكرهون النصح ولا يحبون الناصحين."], "k": "«ولكن لا تحبون الناصحين»… كيف أستقبل النصيحة: بصدر مفتوح، أم بضيق ممن نصحني؟"}, {"lbl": "الآيات ٨٠ – ٨٤", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ﴿٨٠﴾ إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ﴿٨١﴾ وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ﴿٨٢﴾ فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٨٣﴾ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ﴿٨٤﴾", "w": [["ولوطاً", "أي وأرسلنا لوطاً، ولوط هو لوط بن هاران ابن أخي إبراهيم ﵇، وُلد في بابل العراق."], ["الفاحشة", "الخصلة القبيحة، وهي إتيان الرجال في أدبارهم."], ["من العالمين", "أي من الناس."], ["من الغابرين", "الباقين في العذاب."], ["وأمطرنا", "أنزلنا عليهم حجارة من السماء كالمطر فأهلكتهم."], ["المجرمين", "المفسدين للعقائد والأخلاق والأعراض."]], "m": "هذا القصص الرابع: لوط ابن أخي إبراهيم ﵇، أرسله الله إلى قومه من أهل سدوم، ولم يكن منهم، فهو من أرض بابل العراق، هاجر مع عمه إبراهيم، فأرسله الله إلى أهل سدوم وعمورة قرب بحيرة لوط بالأردن. إذ قال لقومه منكراً: أتأتون الفاحشة، إتيان الرجال في أدبارهم، ما سبقكم بها من أحد من العالمين؟ وواصل توبيخ هؤلاء الذين هبطت أخلاقهم إلى درك لم يهبط إليه غيرهم: إنكم لتأتون الرجال شهوة من دون النساء، بل أنتم قوم مسرفون، وإلا فالشهوة من النساء هي المفطور عليها الإنسان، ولكنه الإجرام والتوغّل في الشر والإسراف فيه، والإسراف صاحبه لا يقف عند حد. فما كان جواب قومه إلا أن قالوا: أخرجوا لوطاً والمؤمنين معه من قريتكم سدوم، إنهم أناس يتطهّرون من الخبث الذي هم منغمسون فيه. فأنجيناه وأهله من بناته وبعض نسائه، إلا امرأته كانت من الغابرين، أمرهم بالخروج من البلاد ليلاً قبل حلول العذاب، فما إن غادروا حتى جعل الله عاليها سافلها، وأمطر عليها حجارة من سجّيل فأُهلكوا أجمعين، فانظر كيف كان عاقبة المجرمين، خطاب عام لكل من يسمع هذا القصص ليعتبر.", "h": ["شدة قبح جريمة اللواط.", "أول من عرف هذه الجريمة القذرة هم قوم لوط ﵇.", "الإسراف وعدم الاعتدال في الأقوال والأفعال يتولّد عنه كل شر وفساد.", "الكفر والإجرام يحلّ رابطة الأخوة والقرابة بين أصحابه والبرآء منه.", "من أتى هذه الفاحشة من المحصنين يُرجم بالحجارة حتى الموت."], "k": "«إنهم أناس يتطهّرون»… صار الطُّهر تهمة عند قوم لوط؛ فهل أثبت على الطهارة ولو استغربها الناس؟"}, {"lbl": "الآيات ٨٥ – ٨٧", "q": "وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٨٥﴾ وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿٨٦﴾ وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ﴿٨٧﴾", "w": [["وإلى مدين أخاهم شعيباً", "مدين أبو القبيلة، وهو مدين بن إبراهيم الخليل، وشعيب من أبناء القبيلة، فهو أخوهم في النسب حقيقة، إذ هو شعيب بن ميكائيل بن يشجر بن مدين."], ["ولا تبخسوا الناس أشياءهم", "لا تنقصوا الناس قيم سلعهم وبضائعهم، إذ كانوا يفعلون ذلك."], ["صراط توعدون", "طريق، وتوعدون: تخيفون المارّة وتأخذون عليهم المكوس أو تسلبونهم أمتعتهم."], ["وتبغونها عوجاً", "تريدون سبيل الله، وهي شريعته، معوجّة حتى توافق ميولكم."], ["المفسدين", "الذين يعملون بالمعاصي في البلاد."], ["يحكم بيننا", "يفصل بيننا، فينجي المؤمنين ويهلك الكافرين."]], "m": "هذا القصص الخامس: شعيب مع قومه أهل مدين. وأرسلنا إلى مدين أخاهم شعيباً، قال: يا قوم اعبدوا الله ما لكم من إله غيره، ولازم ذلك أن يصدّقوه حتى يعبدوا الله بما يحب، قد جاءتكم بيّنة من ربكم تشهد لي بالرسالة، فأوفوا الكيل والميزان بالعدل، ولا تبخسوا الناس أشياءهم بل أعطوهم ما تستحقه بضائعهم بحسب جودتها، ولا تفسدوا في الأرض بعد إصلاحها بالشرك والذنوب والتلصّص والتطفيف، ذلكم خير لكم حالاً ومآلاً إن كنتم مؤمنين. ونهاهم عن أبشع الإجرام: ولا تقعدوا بكل صراط، في مداخل البلاد وأفواه السكك، توعدون المارّة إن هم جلسوا إلى شعيب، وتصدّون عن سبيل الله من آمن به، وتبغونها عوجاً، كما كانوا يقطعون الطرق ويسلبون الناس أو يفرضون عليهم ضريبة. واذكروا إذ كنتم قليلاً فكثّركم فأصبحتم شعباً كبيراً، وانظروا كيف كان عاقبة المفسدين من الأمم المجاورة. ثم هدّدهم بحكم الله: وإن كان طائفة منكم آمنوا بالذي أُرسلت به وطائفة لم يؤمنوا، فاصبروا حتى يحكم الله بيننا، وهو خير الحاكمين.", "h": ["دعوة الرسل واحدة في باب العقيدة، إذ كلها تقوم على أساس التوحيد والطاعة.", "حرمة التطفيف في الكيل والميزان، وبخس الناس أشياءهم، ويدخل في ذلك الصناعات وحرف المهن وما إلى ذلك.", "حرمة الفساد في الأرض بالمعاصي، لا سيما البلاد التي طهّرها الله بالإسلام وأصلحها.", "حرمة التلصّص وقطع الطرق وتخويف المارّة.", "حرمة الصد عن سبيل الله بمنع الناس من التديّن والالتزام بالشريعة ظاهراً وباطناً."], "k": "«ولا تبخسوا الناس أشياءهم»… هل أُعطي عمل غيري وجهده حقه من الثناء والأجر، أم أبخسه؟"}]$j$::jsonb then 0 else 1 end;
delete from public.tdb_cards where topic = 105;
insert into public.tdb_cards(topic, i, body) select 105, x.i::int, x.e from jsonb_array_elements($j$[{"lbl": "الآيات ٧٣ – ٧٦", "q": "وَإِلَىٰ ثَمُودَ أَخَاهُمۡ صَٰلِحٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ﴿٧٣﴾ وَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ عَادٖ وَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ﴿٧٤﴾ قَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ ﴿٧٥﴾ قَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ ﴿٧٦﴾", "w": [["وإلى ثمود", "أرسلنا إلى ثمود، وثمود قبيلة سُمّيت باسم جدها، وهو ثمود بن عابر بن إرم بن سام بن نوح."], ["أخاهم صالحاً", "أي في النسب، وصالح هو صالح بن عبيد بن آسف بن ماشح بن عبيد بن حاذر بن ثمود."], ["آية", "علامة على صدقي في أني رسول الله إليكم."], ["وبوّأكم في الأرض", "أنزلكم فيها منازل تحبون فيها."], ["وتنحتون", "تنجرون الحجارة في الجبال لتتخذوا منازل تسكنونها."], ["آلاء الله", "نعم الله تعالى، وهي كثيرة."], ["ولا تعثوا", "لا تفسدوا في الأرض مفسدين."], ["استكبروا", "عتوا وطغوا وتكبّروا فلم يقبلوا الحق ولم يعترفوا به."]], "m": "وأرسلنا إلى قبيلة ثمود أخاهم صالحاً بكلمة التوحيد: يا قوم اعبدوا الله ما لكم من إله غيره، وهذا مدلول «لا إله إلا الله»، قد جاءتكم بيّنة من ربكم تشهد بأني رسوله، وهي ناقة تخرج من صخرة في جبل: هذه ناقة الله لكم آية، فذروها تأكل في أرض الله ولا تمسّوها بسوء فيأخذكم عذاب أليم. فكانت ترعى في المرج وتأتي إلى ماء القوم فتشربه كله، فيتحوّل في بطنها لبناً خالصاً فيحلبون ما شاؤوا، وجعل لها شرباً ولهم شرب يوم معلوم. ووعظهم: واذكروا إذ جعلكم خلفاء من بعد عاد، وكانت ديار عاد بحضرموت جنوب الجزيرة، وديار ثمود بالحجر شمالها بين الحجاز والشام، وبوّأكم في الأرض تتخذون من سهولها قصوراً تسكنونها في الصيف، وتنحتون الجبال بيوتاً تسكنونها في الشتاء، فاذكروا آلاء الله لتشكروها بعبادته وحده، ولا تعثوا في الأرض مفسدين بالشرك والمعاصي. فقال الملأ الذين استكبروا للمؤمنين من ضعفة القوم سخرية: أتعلمون أن صالحاً مرسل من ربه؟ قالوا صريحة غير خائفين: إنا بما أُرسل به مؤمنون، قال المستكبرون: إنا بالذي آمنتم به كافرون، ولم يقولوا «بما أُرسل به» حتى لا يعترفوا بالرسالة ولو في جواب.", "h": ["اتحاد دعوة الرسل في الإيمان بالله والكفر بالطاغوت، أي في عبادة الله وحده.", "تقرير إرسال الرسل بالآيات، وهي المعجزات، وآية صالح أعجب آية، وهي الناقة.", "وجوب التذكير بنعم الله، إذ هو الباعث على الشكر، والشكر هو الطاعة.", "النهي عن الفساد في الأرض بالشرك وارتكاب المعاصي.", "الضعفة هم غالباً أتباع الأنبياء، وذلك لخلوّهم من الموانع، كالمحافظة على المنصب أو الجاه أو المال، وعدم انغماسهم في الملاذّ والشهوات."], "k": "«إنا بما أُرسل به مؤمنون»… الضعفاء قالوها بلا خوف؛ فهل أُعلن الحق حين يسخر منه الأقوياء؟"}, {"lbl": "الآيات ٧٧ – ٧٩", "q": "فَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ ﴿٧٧﴾ فَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ فَأَصۡبَحُواْ فِي دَارِهِمۡ جَٰثِمِينَ ﴿٧٨﴾ فَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّـٰصِحِينَ ﴿٧٩﴾", "w": [["فعقروا الناقة", "نحروها بعد أن عقروا قوائمها، أي قطعوها، والناقة هي الآية."], ["وعتوا عن أمر ربهم", "تمرّدوا عن الأمر وعصوا فلم يطيعوا."], ["الرجفة", "المرة من رجف إذا اضطرب، وذلك لما سمعوا الصيحة أخذتهم الرجفة."], ["جاثمين", "باركين على الركب كما يجثم الطير، أي هلكى على ركبهم."], ["فتولّى عنهم", "بعد أن هلكوا نظر إليهم صالح وهم جاثمون، وقال راثياً لحالهم: «يا قوم لقد أبلغتكم رسالة ربي…» إلى قوله: «ولكن لا تحبون الناصحين»، ثم أعرض عنهم وانصرف."]], "m": "بعد تلك الدعوة الطويلة، والمستكبرون يردّونها بصلف، وقد أوتوا الناقة آية مبصرة، تمالؤوا أخيراً على قتلها: فعقروا الناقة، قطعوا أرجلها ثم نحروها، وعتوا عن أمر ربهم، إذ أمرهم أن يتركوها ولا يمسّوها بسوء، فعقروها تحدّياً وعناداً، وقالوا: يا صالح، بدل أن يقولوا: يا رسول الله، ائتنا بما تعدنا من العذاب إن كنت من المرسلين. فأخذتهم الرجفة، هزّة عنيفة اضطربت لها القلوب والنفوس، فأصبحوا في دارهم جاثمين هلكى على ركبهم. ولما هلكوا وقف عليهم صالح كالمودّع، كما وقف رسول الله ﷺ على أهل القليب ببدر فناداهم: يا فلان يا فلان، فقال كالراثي المتحسّر: يا قوم لقد أبلغتكم رسالة ربي ونصحت لكم ولكن لا تحبون الناصحين، وتولّى عنهم وانصرف.", "h": ["حلول نقمة الله تعالى بكل من عتا عن أمره سبحانه وتعالى.", "مشروعية الرثاء لمن مات أو أُصيب بمصاب عظيم.", "علامة قرب ساعة الهلاك إذا أصبح الناس يكرهون النصح ولا يحبون الناصحين."], "k": "«ولكن لا تحبون الناصحين»… كيف أستقبل النصيحة: بصدر مفتوح، أم بضيق ممن نصحني؟"}, {"lbl": "الآيات ٨٠ – ٨٤", "q": "وَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ﴿٨٠﴾ إِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ﴿٨١﴾ وَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ﴿٨٢﴾ فَأَنجَيۡنَٰهُ وَأَهۡلَهُۥٓ إِلَّا ٱمۡرَأَتَهُۥ كَانَتۡ مِنَ ٱلۡغَٰبِرِينَ ﴿٨٣﴾ وَأَمۡطَرۡنَا عَلَيۡهِم مَّطَرٗاۖ فَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُجۡرِمِينَ ﴿٨٤﴾", "w": [["ولوطاً", "أي وأرسلنا لوطاً، ولوط هو لوط بن هاران ابن أخي إبراهيم ﵇، وُلد في بابل العراق."], ["الفاحشة", "الخصلة القبيحة، وهي إتيان الرجال في أدبارهم."], ["من العالمين", "أي من الناس."], ["من الغابرين", "الباقين في العذاب."], ["وأمطرنا", "أنزلنا عليهم حجارة من السماء كالمطر فأهلكتهم."], ["المجرمين", "المفسدين للعقائد والأخلاق والأعراض."]], "m": "هذا القصص الرابع: لوط ابن أخي إبراهيم ﵇، أرسله الله إلى قومه من أهل سدوم، ولم يكن منهم، فهو من أرض بابل العراق، هاجر مع عمه إبراهيم، فأرسله الله إلى أهل سدوم وعمورة قرب بحيرة لوط بالأردن. إذ قال لقومه منكراً: أتأتون الفاحشة، إتيان الرجال في أدبارهم، ما سبقكم بها من أحد من العالمين؟ وواصل توبيخ هؤلاء الذين هبطت أخلاقهم إلى درك لم يهبط إليه غيرهم: إنكم لتأتون الرجال شهوة من دون النساء، بل أنتم قوم مسرفون، وإلا فالشهوة من النساء هي المفطور عليها الإنسان، ولكنه الإجرام والتوغّل في الشر والإسراف فيه، والإسراف صاحبه لا يقف عند حد. فما كان جواب قومه إلا أن قالوا: أخرجوا لوطاً والمؤمنين معه من قريتكم سدوم، إنهم أناس يتطهّرون من الخبث الذي هم منغمسون فيه. فأنجيناه وأهله من بناته وبعض نسائه، إلا امرأته كانت من الغابرين، أمرهم بالخروج من البلاد ليلاً قبل حلول العذاب، فما إن غادروا حتى جعل الله عاليها سافلها، وأمطر عليها حجارة من سجّيل فأُهلكوا أجمعين، فانظر كيف كان عاقبة المجرمين، خطاب عام لكل من يسمع هذا القصص ليعتبر.", "h": ["شدة قبح جريمة اللواط.", "أول من عرف هذه الجريمة القذرة هم قوم لوط ﵇.", "الإسراف وعدم الاعتدال في الأقوال والأفعال يتولّد عنه كل شر وفساد.", "الكفر والإجرام يحلّ رابطة الأخوة والقرابة بين أصحابه والبرآء منه.", "من أتى هذه الفاحشة من المحصنين يُرجم بالحجارة حتى الموت."], "k": "«إنهم أناس يتطهّرون»… صار الطُّهر تهمة عند قوم لوط؛ فهل أثبت على الطهارة ولو استغربها الناس؟"}, {"lbl": "الآيات ٨٥ – ٨٧", "q": "وَإِلَىٰ مَدۡيَنَ أَخَاهُمۡ شُعَيۡبٗاۚ قَالَ يَٰقَوۡمِ ٱعۡبُدُواْ ٱللَّهَ مَا لَكُم مِّنۡ إِلَٰهٍ غَيۡرُهُۥۖ قَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ فَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ﴿٨٥﴾ وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ وَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ وَٱنظُرُواْ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ﴿٨٦﴾ وَإِن كَانَ طَآئِفَةٞ مِّنكُمۡ ءَامَنُواْ بِٱلَّذِيٓ أُرۡسِلۡتُ بِهِۦ وَطَآئِفَةٞ لَّمۡ يُؤۡمِنُواْ فَٱصۡبِرُواْ حَتَّىٰ يَحۡكُمَ ٱللَّهُ بَيۡنَنَاۚ وَهُوَ خَيۡرُ ٱلۡحَٰكِمِينَ ﴿٨٧﴾", "w": [["وإلى مدين أخاهم شعيباً", "مدين أبو القبيلة، وهو مدين بن إبراهيم الخليل، وشعيب من أبناء القبيلة، فهو أخوهم في النسب حقيقة، إذ هو شعيب بن ميكائيل بن يشجر بن مدين."], ["ولا تبخسوا الناس أشياءهم", "لا تنقصوا الناس قيم سلعهم وبضائعهم، إذ كانوا يفعلون ذلك."], ["صراط توعدون", "طريق، وتوعدون: تخيفون المارّة وتأخذون عليهم المكوس أو تسلبونهم أمتعتهم."], ["وتبغونها عوجاً", "تريدون سبيل الله، وهي شريعته، معوجّة حتى توافق ميولكم."], ["المفسدين", "الذين يعملون بالمعاصي في البلاد."], ["يحكم بيننا", "يفصل بيننا، فينجي المؤمنين ويهلك الكافرين."]], "m": "هذا القصص الخامس: شعيب مع قومه أهل مدين. وأرسلنا إلى مدين أخاهم شعيباً، قال: يا قوم اعبدوا الله ما لكم من إله غيره، ولازم ذلك أن يصدّقوه حتى يعبدوا الله بما يحب، قد جاءتكم بيّنة من ربكم تشهد لي بالرسالة، فأوفوا الكيل والميزان بالعدل، ولا تبخسوا الناس أشياءهم بل أعطوهم ما تستحقه بضائعهم بحسب جودتها، ولا تفسدوا في الأرض بعد إصلاحها بالشرك والذنوب والتلصّص والتطفيف، ذلكم خير لكم حالاً ومآلاً إن كنتم مؤمنين. ونهاهم عن أبشع الإجرام: ولا تقعدوا بكل صراط، في مداخل البلاد وأفواه السكك، توعدون المارّة إن هم جلسوا إلى شعيب، وتصدّون عن سبيل الله من آمن به، وتبغونها عوجاً، كما كانوا يقطعون الطرق ويسلبون الناس أو يفرضون عليهم ضريبة. واذكروا إذ كنتم قليلاً فكثّركم فأصبحتم شعباً كبيراً، وانظروا كيف كان عاقبة المفسدين من الأمم المجاورة. ثم هدّدهم بحكم الله: وإن كان طائفة منكم آمنوا بالذي أُرسلت به وطائفة لم يؤمنوا، فاصبروا حتى يحكم الله بيننا، وهو خير الحاكمين.", "h": ["دعوة الرسل واحدة في باب العقيدة، إذ كلها تقوم على أساس التوحيد والطاعة.", "حرمة التطفيف في الكيل والميزان، وبخس الناس أشياءهم، ويدخل في ذلك الصناعات وحرف المهن وما إلى ذلك.", "حرمة الفساد في الأرض بالمعاصي، لا سيما البلاد التي طهّرها الله بالإسلام وأصلحها.", "حرمة التلصّص وقطع الطرق وتخويف المارّة.", "حرمة الصد عن سبيل الله بمنع الناس من التديّن والالتزام بالشريعة ظاهراً وباطناً."], "k": "«ولا تبخسوا الناس أشياءهم»… هل أُعطي عمل غيري وجهده حقه من الثناء والأجر، أم أبخسه؟"}]$j$::jsonb) with ordinality x(e, i);
select n, title, pub, (select count(*) from public.tdb_cards c where c.topic=t.n) cards from public.tdb_topics t where n>=36 order by n;